// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.17;

import { SafeTransferLib } from "solady/utils/SafeTransferLib.sol";

/// Library to handle basic token functions for ERC20s & ETH (represented by 0x0)

interface ERC20 {
    function decimals() external view returns (uint8);
    function balanceOf(address addr) external view returns (uint256);
}

library TokenUtils {
    using SafeTransferLib for address;

    address internal constant ETH_ADDRESS = address(0);

    function _safeTransfer(address token, address addr, uint256 amount) internal {
        if (_isETH(token)) addr.safeTransferETH(amount);
        else token.safeTransfer(addr, amount);
    }

    function _decimals(address token) internal view returns (uint8) {
        return _isETH(token) ? 18 : ERC20(token).decimals();
    }

    function _balanceOf(address token, address addr) internal view returns (uint256) {
        return _isETH(token) ? addr.balance : ERC20(token).balanceOf(addr);
    }

    function _isETH(address token) internal pure returns (bool) {
        return (token == ETH_ADDRESS);
    }
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.25;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IMultistrategyVault } from "src/core/interfaces/IMultistrategyVault.sol";

/**
 * @title ERC20 Safe Approve Library
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Library for safe ERC20 approve operations handling non-standard tokens
 * @dev Handles tokens that don't return bool or revert silently
 *
 *      PROBLEM SOLVED:
 *      - Some tokens (USDT, BNB) don't return bool from approve()
 *      - Some tokens revert silently on approval failure
 *      - Standard Solidity expects bool return value
 *
 *      SOLUTION:
 *      - Uses low-level call to handle any return data format
 *      - Validates success flag
 *      - Validates return data if present
 *      - Reverts with ApprovalFailed() on any failure
 *
 * @custom:security Critical for compatibility with non-standard ERC20 tokens
 */
library ERC20SafeApproveLib {
    /**
     * @notice Safely approves ERC20 tokens handling non-standard implementations
     * @dev Uses low-level call to handle tokens that:
     *      - Don't return bool (e.g., USDT)
     *      - Return false instead of reverting
     *      - Have non-standard approval behavior
     * @param token ERC20 token address
     * @param spender Address being approved to spend tokens
     * @param amount Amount to approve
     * @custom:security Reverts with ApprovalFailed() on any failure
     */
    function safeApprove(address token, address spender, uint256 amount) external {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20.approve.selector, spender, amount)
        );
        if (!success || (data.length > 0 && !abi.decode(data, (bool)))) {
            revert IMultistrategyVault.ApprovalFailed();
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity >=0.8.18;

/**
 * @title Privileged
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Mixin providing privileged address storage and management functions.
 * @dev Uses ERC-7201 namespaced storage to avoid collisions.
 *      Inheriting contracts must implement access control for setPrivileged/setPrivilegedBatch.
 */
abstract contract Privileged {
    event PrivilegedUpdated(address indexed account, bool status);

    bytes32 internal constant PRIVILEGED_STORAGE =
        keccak256(abi.encode(uint256(keccak256("octant.privileged.strategy.storage")) - 1)) & ~bytes32(uint256(0xff));

    struct PrivilegedData {
        mapping(address => bool) privileged;
    }

    function _privilegedStorage() internal pure returns (PrivilegedData storage P) {
        bytes32 slot = PRIVILEGED_STORAGE;
        assembly {
            P.slot := slot
        }
    }

    function _setPrivileged(address _account, bool _status) internal {
        PrivilegedData storage P = _privilegedStorage();
        // Skip SSTORE + event when the flag is already at the requested value.
        // Avoids spurious PrivilegedUpdated logs that would skew off-chain indexer timelines.
        if (P.privileged[_account] == _status) return;
        P.privileged[_account] = _status;
        emit PrivilegedUpdated(_account, _status);
    }

    function _setPrivilegedBatch(address[] calldata _accounts, bool _status) internal {
        PrivilegedData storage P = _privilegedStorage();
        for (uint256 i = 0; i < _accounts.length; i++) {
            // Skip per-entry no-ops so the batch emits only on real changes.
            if (P.privileged[_accounts[i]] == _status) continue;
            P.privileged[_accounts[i]] = _status;
            emit PrivilegedUpdated(_accounts[i], _status);
        }
    }

    /// @notice Checks if an account has privileged status.
    /// @param _account The address to check.
    /// @return True if the account is privileged, false otherwise.
    function isPrivileged(address _account) public view returns (bool) {
        return _privilegedStorage().privileged[_account];
    }
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity >=0.8.25;

import { YieldDonatingTokenizedStrategy } from "./YieldDonatingTokenizedStrategy.sol";
import { Privileged } from "src/core/Privileged.sol";

/**
 * @title Privileged Yield Donating Tokenized Strategy
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice YieldDonatingTokenizedStrategy with privileged-gated deposits and mints.
 */
contract PrivilegedYieldDonatingTokenizedStrategy is YieldDonatingTokenizedStrategy, Privileged {
    /// @notice Grant or revoke privileged status for a single account.
    function setPrivileged(address _account, bool _status) external onlyManagement {
        _setPrivileged(_account, _status);
    }

    /// @notice Grant or revoke privileged status for a batch of accounts.
    function setPrivilegedBatch(address[] calldata _accounts, bool _status) external onlyManagement {
        _setPrivilegedBatch(_accounts, _status);
    }

    /// @notice Deposit assets from a privileged caller. The receiver does not need to be privileged.
    /// @dev Only the caller is gated. A receiver-side check would be redundant because
    ///      ERC-20 transfers are ungated, so once shares are minted they can move to any
    ///      address. Restricting to caller-only unblocks legitimate mint-to-contract flows
    ///      (splitters, aggregators, integrator vaults) while preserving the real trust
    ///      boundary: who can initiate new share issuance.
    function deposit(uint256 assets, address receiver) public override returns (uint256) {
        require(isPrivileged(msg.sender), "!privileged");
        return super.deposit(assets, receiver);
    }

    /// @notice Mint shares from a privileged caller. The receiver does not need to be privileged.
    /// @dev Caller-only gate; see `deposit` for the rationale.
    function mint(uint256 shares, address receiver) public override returns (uint256) {
        require(isPrivileged(msg.sender), "!privileged");
        return super.mint(shares, receiver);
    }

    /// @notice Returns 0 for non-privileged receivers so front-ends steer users toward the
    ///         privileged path; a privileged caller may still deposit on their behalf.
    function maxDeposit(address receiver) public view override returns (uint256) {
        if (!isPrivileged(receiver)) return 0;
        return super.maxDeposit(receiver);
    }

    /// @notice Returns 0 for non-privileged receivers so front-ends steer users toward the
    ///         privileged path; a privileged caller may still mint on their behalf.
    function maxMint(address receiver) public view override returns (uint256) {
        if (!isPrivileged(receiver)) return 0;
        return super.maxMint(receiver);
    }
}

// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.8.0 <0.9.0;

/**
 * @title Multi Send Call Only - Allows to batch multiple transactions into one, but only calls
 * @notice The guard logic is not required here as this contract doesn't support nested delegate calls
 * @author Stefan George - @Georgi87
 * @author Richard Meissner - @rmeissner
 * @custom:security-contact security@golem.foundation
 * @custom:ported-from https://github.com/safe-global/safe-smart-account/blob/main/contracts/libraries/MultiSendCallOnly.sol
 */
contract MultiSendCallOnly {
    /**
     * @dev Sends multiple transactions and reverts all if one fails.
     * @param transactions Encoded transactions. Each transaction is encoded as a packed bytes of
     *                     operation has to be uint8(0) in this version (=> 1 byte),
     *                     to as a address (=> 20 bytes),
     *                     value as a uint256 (=> 32 bytes),
     *                     data length as a uint256 (=> 32 bytes),
     *                     data as bytes.
     *                     see abi.encodePacked for more information on packed encoding
     * @notice The code is for the most part the same as the normal MultiSend (to keep compatibility),
     *         but reverts if a transaction tries to use a delegatecall.
     * @notice This method is payable as delegatecalls keep the msg.value from the previous call
     *         If the calling method (e.g. execTransaction) received ETH this would revert otherwise
     */
    function multiSend(bytes memory transactions) public payable {
        /* solhint-disable no-inline-assembly */
        /// @solidity memory-safe-assembly
        assembly {
            let length := mload(transactions)
            let i := 0x20
            for {
                // Pre block is not used in "while mode"
            } lt(i, length) {
                // Post block is not used in "while mode"
            } {
                // First byte of the data is the operation.
                // We shift by 248 bits (256 - 8 [operation byte]) it right since mload will always load 32 bytes (a word).
                // This will also zero out unused data.
                let operation := shr(0xf8, mload(add(transactions, i)))
                // We offset the load address by 1 byte (operation byte)
                // We shift it right by 96 bits (256 - 160 [20 address bytes]) to right-align the data and zero out unused data.
                let to := shr(0x60, mload(add(transactions, add(i, 0x01))))
                // Defaults `to` to `address(this)` if `address(0)` is provided.
                to := or(to, mul(iszero(to), address()))
                // We offset the load address by 21 byte (operation byte + 20 address bytes)
                let value := mload(add(transactions, add(i, 0x15)))
                // We offset the load address by 53 byte (operation byte + 20 address bytes + 32 value bytes)
                let dataLength := mload(add(transactions, add(i, 0x35)))
                // We offset the load address by 85 byte (operation byte + 20 address bytes + 32 value bytes + 32 data length bytes)
                let data := add(transactions, add(i, 0x55))
                let success := 0
                switch operation
                case 0 {
                    success := call(gas(), to, value, data, dataLength, 0, 0)
                }
                // This version does not allow delegatecalls
                case 1 {
                    revert(0, 0)
                }
                if iszero(success) {
                    let ptr := mload(0x40)
                    returndatacopy(ptr, 0, returndatasize())
                    revert(ptr, returndatasize())
                }
                // Next entry starts at 85 byte + data length
                i := add(i, add(0x55, dataLength))
            }
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity >=0.8.25;

import { BaseStrategyFactory } from "../BaseStrategyFactory.sol";
import { RocketPoolStrategy } from "src/strategies/yieldSkimming/RocketPoolStrategy.sol";

/**
 * @title RocketPoolStrategyFactory
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Factory for deploying RocketPool yield skimming strategies
 * @dev Inherits deterministic deployment from BaseStrategyFactory
 */
contract RocketPoolStrategyFactory is BaseStrategyFactory {
    /// @notice rETH token address on mainnet
    address public constant R_ETH = 0xae78736Cd615f374D3085123A210448E74Fc6393;

    /// @notice Emitted when a new RocketPoolStrategy is deployed
    /// @param deployer Address that deployed the strategy
    /// @param donationAddress Dragon router address that receives profit shares
    /// @param strategyAddress Deployed strategy address
    /// @param vaultTokenName Strategy share token name
    event StrategyDeploy(
        address indexed deployer,
        address indexed donationAddress,
        address indexed strategyAddress,
        string vaultTokenName
    );

    /**
     * @notice Deploys a new RocketPool strategy for the Yield Skimming Vault
     * @dev Uses deterministic deployment based on strategy parameters to prevent duplicates
     * @param _name Strategy share token name
     * @param _symbol Strategy share token symbol
     * @param _management Management address (can update params)
     * @param _keeper Keeper address (calls report)
     * @param _emergencyAdmin Emergency admin address
     * @param _donationAddress Dragon router address (receives profit shares)
     * @param _enableBurning True to enable burning shares during loss protection
     * @param _tokenizedStrategyAddress TokenizedStrategy implementation address
     * @return strategyAddress Deployed RocketPoolStrategy address
     */
    function createStrategy(
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    ) external returns (address strategyAddress) {
        // Generate deterministic hash from all strategy parameters
        bytes32 parameterHash = keccak256(
            abi.encode(
                R_ETH,
                _name,
                _symbol,
                _management,
                _keeper,
                _emergencyAdmin,
                _donationAddress,
                _enableBurning,
                _tokenizedStrategyAddress
            )
        );

        bytes memory bytecode = abi.encodePacked(
            type(RocketPoolStrategy).creationCode,
            abi.encode(
                R_ETH,
                _name,
                _symbol,
                _management,
                _keeper,
                _emergencyAdmin,
                _donationAddress,
                _enableBurning,
                _tokenizedStrategyAddress
            )
        );

        // Deploy using parameter hash to prevent duplicates
        strategyAddress = _deployStrategy(bytecode, parameterHash);

        emit StrategyDeploy(msg.sender, _donationAddress, strategyAddress, _name);

        // Record the deployment
        _recordStrategy(_name, _donationAddress, strategyAddress);
    }

    /// @inheritdoc BaseStrategyFactory
    function computeStrategyAddress(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress,
        address _deployer
    ) public view override returns (address) {
        if (_vault != R_ETH) revert InvalidVault(_vault, R_ETH);
        if (_asset != R_ETH) revert InvalidAsset(_asset, R_ETH);

        bytes32 parameterHash = keccak256(
            abi.encode(
                R_ETH,
                _name,
                _symbol,
                _management,
                _keeper,
                _emergencyAdmin,
                _donationAddress,
                _enableBurning,
                _tokenizedStrategyAddress
            )
        );

        bytes memory bytecode = abi.encodePacked(
            type(RocketPoolStrategy).creationCode,
            abi.encode(
                R_ETH,
                _name,
                _symbol,
                _management,
                _keeper,
                _emergencyAdmin,
                _donationAddress,
                _enableBurning,
                _tokenizedStrategyAddress
            )
        );

        return _predictStrategyAddress(parameterHash, _deployer, bytecode);
    }
}

// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.17;

import { ERC20 } from "solady/tokens/ERC20.sol";
import { ISwapRouter } from "src/utils/vendor/uniswap/ISwapRouter.sol";
import { WETH } from "solady/tokens/WETH.sol";
import { QuoteParams } from "./LibQuotes.sol";
import { SafeTransferLib } from "solady/utils/SafeTransferLib.sol";
import { TokenUtils } from "./TokenUtils.sol";

import { ISwapperFlashCallback } from "./ISwapperFlashCallback.sol";
import { ISwapperImpl } from "./SwapperImpl.sol";
import { ISwapperFactory } from "./ISwapperFactory.sol";

/// @title Uniswap V3 Swapper Integration
/// @author 0xSplits
/// @notice Used by EOAs & simple bots to execute `Swapper#flash` with uniswap v3
/// @dev This contract uses token = address(0) to refer to ETH.
contract UniV3Swap is ISwapperFlashCallback {
    using SafeTransferLib for address;
    using TokenUtils for address;

    struct InitFlashParams {
        QuoteParams[] quoteParams;
        FlashCallbackData flashCallbackData;
    }

    struct FlashCallbackData {
        ISwapRouter.ExactInputParams[] exactInputParams;
        address excessRecipient;
    }

    ISwapperFactory public immutable swapperFactory;
    ISwapRouter public immutable swapRouter;
    WETH public immutable weth9;

    error Unauthorized();
    error InsufficientFunds();

    constructor(ISwapperFactory swapperFactory_, ISwapRouter swapRouter_, WETH weth9_) {
        swapperFactory = swapperFactory_;
        swapRouter = swapRouter_;
        weth9 = weth9_;
    }

    /// receive from weth9
    receive() external payable {}

    /// begin `Swapper#flash`
    /// @dev trader may pay ETH & include the extra WETH in `params_.exactInputParams` to make up
    /// for `Swapper#oracle` shortfall. If swapper incentives are insufficient and they still want to push
    /// funds to `beneficiary`. Recipient in `params_.exactInputParams` should always be _this_ contract
    /// so it can handle the approval / payback for Swapper
    function initFlash(ISwapperImpl swapper, InitFlashParams calldata params_) external payable {
        swapper.flash(params_.quoteParams, abi.encode(params_.flashCallbackData));
    }

    /// `Swapper#flash` callback
    /// @dev by end of function if `tokenToBeneficiary_` is ETH, must have sent `amountToBeneficiary_`
    /// to `Swapper#payback`. Otherwise, must approve Swapper to transfer `amountToBeneficiary_`
    /// DO NOT HOLD FUNDS IN THIS CONTRACT WITHOUT ADDING PROPER VERIFICATION OF MSG.SENDER
    function swapperFlashCallback(
        address tokenToBeneficiary_,
        uint256 amountToBeneficiary_,
        bytes calldata data_
    ) external {
        FlashCallbackData memory flashCallbackData = abi.decode(data_, (FlashCallbackData));
        ISwapRouter.ExactInputParams[] memory exactInputParams = flashCallbackData.exactInputParams;

        uint256 ethBalance = address(this).balance;
        if (ethBalance != 0) {
            weth9.deposit{ value: ethBalance }();
        }

        uint256 totalOut = (tokenToBeneficiary_._isETH())
            ? weth9.balanceOf(address(this))
            : tokenToBeneficiary_.balanceOf(address(this));

        uint256 length = exactInputParams.length;
        for (uint256 i; i < length; ) {
            ISwapRouter.ExactInputParams memory eip = exactInputParams[i];
            address token = _getStartTokenFromPath(eip.path);

            token.safeApprove(address(swapRouter), eip.amountIn);
            totalOut += swapRouter.exactInput(eip);

            unchecked {
                ++i;
            }
        }

        if (totalOut < amountToBeneficiary_) revert InsufficientFunds();

        address excessRecipient = flashCallbackData.excessRecipient;
        if (tokenToBeneficiary_._isETH()) {
            // withdraw WETH from uni swaps to ETH
            uint256 weth9Balance = weth9.balanceOf(address(this));
            weth9.withdraw(weth9Balance);

            // send req'd amt to swapper#payback
            // False positive: totalAmount out is checked before sending
            //slither-disable-next-line arbitrary-send-eth
            ISwapperImpl(msg.sender).payback{ value: amountToBeneficiary_ }();

            // xfr excess out
            ethBalance = address(this).balance;
            if (ethBalance != 0) {
                excessRecipient.safeTransferETH(ethBalance);
            }
        } else {
            // approve swapper to xfr req'd amt out
            tokenToBeneficiary_.safeApprove(msg.sender, amountToBeneficiary_);

            // xfr excess out
            uint256 excessBalance = ERC20(tokenToBeneficiary_).balanceOf(address(this)) - amountToBeneficiary_;
            if (excessBalance > 0) {
                tokenToBeneficiary_.safeTransfer(excessRecipient, excessBalance);
            }
        }
    }

    function _getStartTokenFromPath(bytes memory path) internal pure returns (address token) {
        assembly {
            token := mload(add(path, 0x14))
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { IAddressSet } from "./IAddressSet.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/**
 * @title AddressSet
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Managed set of addresses for allowlists and blocklists
 * @dev Wrapper around OpenZeppelin's EnumerableSet with owner controls
 *
 *      USE CASES:
 *      - Allowlists: Control who can interact with a contract
 *      - Blocklists: Prevent specific addresses from interacting
 *      - Registry: Track set of authorized addresses
 *
 *      FEATURES:
 *      - O(1) add, remove, contains operations
 *      - Enumerable (can iterate through all addresses)
 *      - Owner-only modifications
 *      - Batch operations supported
 *      - Duplicate prevention
 *
 *      GAS CONSIDERATIONS:
 *      - Add: ~40k gas first time, ~20k subsequent
 *      - Remove: ~20k gas
 *      - Contains: ~200 gas (view)
 *      - Batch operations save gas vs multiple transactions
 */
contract AddressSet is IAddressSet, Ownable {
    using EnumerableSet for EnumerableSet.AddressSet;

    // ============================================
    // ERRORS
    // ============================================

    error IllegalAddressSetOperation(address account, string reason);
    error EmptyArray();

    // ============================================
    // EVENTS
    // ============================================

    /// @notice Emitted when an address is added to or removed from the set
    /// @param account Address that was modified
    /// @param operation Type of operation (Add or Remove)
    event AddressSetAltered(address indexed account, AddressSetOperation indexed operation);

    // ============================================
    // ENUMS
    // ============================================

    /// @notice Operation types for address set modifications
    enum AddressSetOperation {
        Add,
        Remove
    }

    // ============================================
    // STATE VARIABLES
    // ============================================

    /// @notice Internal EnumerableSet storage
    /// @dev Uses OpenZeppelin's gas-optimized implementation
    EnumerableSet.AddressSet private _addresses;

    constructor() Ownable(msg.sender) {}

    function contains(address account) external view override returns (bool) {
        return _addresses.contains(account);
    }

    /// @notice Get all addresses in the set
    /// @return Array of all addresses
    function values() external view returns (address[] memory) {
        return _addresses.values();
    }

    /// @notice Get number of addresses in the set
    /// @return Number of addresses
    function length() external view returns (uint256) {
        return _addresses.length();
    }

    function add(address[] memory accounts) external override onlyOwner {
        require(accounts.length > 0, EmptyArray());

        for (uint256 i = 0; i < accounts.length; i++) {
            if (accounts[i] == address(0)) {
                revert IllegalAddressSetOperation(accounts[i], "Address zero not allowed.");
            }
            if (!_addresses.add(accounts[i])) {
                revert IllegalAddressSetOperation(accounts[i], "Address already in set.");
            }
            emit AddressSetAltered(accounts[i], AddressSetOperation.Add);
        }
    }

    function add(address account) external override onlyOwner {
        if (account == address(0)) {
            revert IllegalAddressSetOperation(account, "Address zero not allowed.");
        }
        if (!_addresses.add(account)) {
            revert IllegalAddressSetOperation(account, "Address already in set.");
        }

        emit AddressSetAltered(account, AddressSetOperation.Add);
    }

    /// @inheritdoc IAddressSet
    function remove(address[] memory accounts) external override onlyOwner {
        require(accounts.length > 0, EmptyArray());

        for (uint256 i = 0; i < accounts.length; i++) {
            if (accounts[i] == address(0)) {
                revert IllegalAddressSetOperation(accounts[i], "Address zero not allowed.");
            }
            if (!_addresses.remove(accounts[i])) {
                revert IllegalAddressSetOperation(accounts[i], "Address not in set.");
            }
            emit AddressSetAltered(accounts[i], AddressSetOperation.Remove);
        }
    }

    /// @inheritdoc IAddressSet
    function remove(address account) external override onlyOwner {
        if (account == address(0)) {
            revert IllegalAddressSetOperation(account, "Address zero not allowed.");
        }
        if (!_addresses.remove(account)) {
            revert IllegalAddressSetOperation(account, "Address not in set.");
        }
        emit AddressSetAltered(account, AddressSetOperation.Remove);
    }
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.0;

import { ERC4626Strategy } from "./ERC4626Strategy.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";

/**
 * @title SparkStrategy
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Specialized yield-donating strategy for Spark Protocol ERC4626 vaults
 * @dev Extends ERC4626Strategy with additional functionality to sweep airdropped tokens
 *      to the dragon router address. This is specifically designed for Spark Protocol
 *      which may airdrop governance tokens or other rewards to strategy addresses.
 *
 *      ADDITIONAL FEATURES:
 *      - Airdrop token sweep functionality for tokens sent to strategy
 *      - Only allows sweeping tokens that are not the main asset or vault shares
 *      - Swept tokens are sent to the dragon router (donation address)
 *      - Callable by both keepers and management for operational flexibility
 *
 * @custom:security Only sweep tokens that are not critical to strategy operation
 */
contract SparkStrategy is ERC4626Strategy {
    using SafeERC20 for IERC20;

    /// @notice Emitted when tokens are swept from the strategy
    /// @param token Address of the token that was swept
    /// @param amount Amount of tokens swept
    /// @param recipient Address that received the swept tokens
    event TokenSwept(address indexed token, uint256 amount, address indexed recipient);

    /**
     * @notice Initializes the Spark strategy
     * @dev Inherits ERC4626Strategy's per-deposit approval flow, which clears
     *      target-vault allowance after each deploy.
     * @param _targetVault Address of the Spark ERC4626 vault this strategy deposits into
     * @param _asset Address of the underlying asset (must match target vault's asset)
     * @param _name Strategy display name (e.g., "Spark USDC Strategy")
     * @param _symbol Strategy token symbol (e.g., "osSparkUSDC")
     * @param _management Address with management permissions
     * @param _keeper Address authorized to call report() and tend()
     * @param _emergencyAdmin Address authorized for emergency shutdown
     * @param _donationAddress Address receiving minted profit shares
     * @param _enableBurning True to enable loss protection via share burning
     * @param _tokenizedStrategyAddress Address of TokenizedStrategy implementation contract
     */
    constructor(
        address _targetVault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    )
        ERC4626Strategy(
            _targetVault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        )
    {}

    /**
     * @notice Sweeps airdropped tokens to the dragon router address
     * @dev Can only be called by keepers or management. Protects against sweeping
     *      critical tokens (asset and vault shares) that are needed for strategy operation.
     * @param _token Address of the token to sweep
     *
     * @custom:security This function:
     * - Only allows sweeping of non-critical tokens
     * - Transfers entire balance to dragon router
     * - Can be called by both keepers and management for operational flexibility
     * - Emits event for transparency
     *
     * @custom:operator-note When `keeper` is a YieldForwarder, this function
     *                      cannot be invoked by the keeper role (YieldForwarder
     *                      exposes no strategy-API proxy). In that configuration
     *                      `management` must retain a separate operational
     *                      channel to call `sweepAirdrop`. If `dragonRouter` is
     *                      also a YieldForwarder, follow the sweep with
     *                      `YieldForwarder.forwardToken(_token)` so the swept
     *                      balance is forwarded to the hardcoded receiver (see
     *                      YieldForwarder NatSpec).
     */
    function sweepAirdrop(address _token) external onlyKeepers {
        // Safety checks: prevent sweeping critical tokens
        require(_token != address(asset), "SparkStrategy: Cannot sweep main asset");
        require(_token != targetVault, "SparkStrategy: Cannot sweep vault shares");

        // Get token balance and dragon router address
        uint256 balance = IERC20(_token).balanceOf(address(this));
        address dragon = TokenizedStrategy.dragonRouter();

        // Only proceed if there's a balance to sweep
        require(balance > 0, "SparkStrategy: No balance to sweep");

        // Transfer all tokens to dragon router
        IERC20(_token).safeTransfer(dragon, balance);

        emit TokenSwept(_token, balance, dragon);
    }
}

