pragma solidity ^0.8.0;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Enum } from "@gnosis.pm/safe-contracts/contracts/common/Enum.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { NATIVE_TOKEN } from "src/constants.sol";
import { ILinearAllowanceSingleton } from "src/zodiac-core/interfaces/ILinearAllowanceSingleton.sol";
import { ISafe } from "src/zodiac-core/interfaces/Safe.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";

/**
 * @title LinearAllowanceSingletonForGnosisSafe
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Singleton contract managing linear allowances for Gnosis Safes
 * @dev Enables Safes to grant delegates time-based spending allowances that accrue linearly
 *
 *      LINEAR ALLOWANCE MECHANISM:
 *      - Safe sets dripRatePerDay for delegate + token pair
 *      - Allowance accrues at dripRatePerDay / 86400 per second
 *      - Delegate can spend up to accrued amount via executeAllowanceTransfer()
 *      - Unspent allowance carries over (totalUnspent tracks balance)
 *
 *      EXAMPLE:
 *      - Safe sets 100 DAI/day drip rate for delegate
 *      - After 12 hours: 50 DAI available
 *      - Delegate spends 30 DAI → 20 DAI unspent
 *      - After 24 more hours: 20 + 100 = 120 DAI available
 *
 *      FEATURES:
 *      - Multiple delegates per Safe
 *      - Multiple tokens per delegate
 *      - Batch operations for gas efficiency
 *      - ETH support via NATIVE_TOKEN constant
 *      - Reentrancy protected
 *
 *      USE CASES:
 *      - Recurring payments to contributors
 *      - Automated treasury operations
 *      - Streaming payment schedules
 *
 *      SECURITY MODEL:
 *      - Safe has full control (set/revoke allowances)
 *      - Delegates can only spend within accrued limits
 *      - Transfers limited by min(accrued, Safe balance)
 *      - CEI pattern (Checks-Effects-Interactions) enforced
 *
 * @custom:security Singleton pattern - one deployment serves all Safes
 * @custom:security Fee-on-transfer tokens NOT supported (balance checks would fail)
 */
contract LinearAllowanceSingletonForGnosisSafe is ILinearAllowanceSingleton, ReentrancyGuard {
    using SafeCast for uint256;

    /// @notice Mapping of allowances per Safe, delegate, and token
    /// @dev Structure: Safe address → delegate address → token address → LinearAllowance
    mapping(address => mapping(address => mapping(address => LinearAllowance))) public allowances;

    function setAllowance(address delegate, address token, uint192 dripRatePerDay) external nonReentrant {
        _setAllowance(msg.sender, delegate, token, dripRatePerDay);
    }

    /// @notice Set multiple allowances in a single transaction
    /// @param delegates Authorized spender addresses
    /// @param tokens Token addresses (use NATIVE_TOKEN for ETH)
    /// @param dripRatesPerDay Drip rates in token base units per day
    function setAllowances(
        address[] calldata delegates,
        address[] calldata tokens,
        uint192[] calldata dripRatesPerDay
    ) external nonReentrant {
        uint256 length = delegates.length;
        require(
            length == tokens.length && length == dripRatesPerDay.length,
            ArrayLengthsMismatch(length, tokens.length, dripRatesPerDay.length)
        );

        for (uint256 i = 0; i < length; i++) {
            _setAllowance(msg.sender, delegates[i], tokens[i], dripRatesPerDay[i]);
        }
    }

    /// @inheritdoc ILinearAllowanceSingleton
    function revokeAllowance(address delegate, address token) external nonReentrant {
        _revokeAllowance(msg.sender, delegate, token);
    }

    /// @inheritdoc ILinearAllowanceSingleton
    function revokeAllowances(address[] calldata delegates, address[] calldata tokens) external nonReentrant {
        uint256 length = delegates.length;
        require(length == tokens.length, ArrayLengthsMismatch(delegates.length, tokens.length, 0));

        for (uint256 i = 0; i < length; i++) {
            _revokeAllowance(msg.sender, delegates[i], tokens[i]);
        }
    }

    function executeAllowanceTransfer(
        address source,
        address token,
        address payable to
    ) external nonReentrant returns (uint256) {
        return _executeAllowanceTransfer(source, msg.sender, token, to);
    }

    /// @notice Execute multiple allowance transfers in a single transaction
    /// @param safes Safe addresses that own the allowances
    /// @param tokens Token addresses to transfer (use NATIVE_TOKEN for ETH)
    /// @param tos Recipient addresses
    /// @return transferAmounts Amounts transferred for each operation in token base units
    function executeAllowanceTransfers(
        address[] calldata safes,
        address[] calldata tokens,
        address[] calldata tos
    ) external nonReentrant returns (uint256[] memory transferAmounts) {
        uint256 length = safes.length;
        require(
            length == tokens.length && length == tos.length,
            ArrayLengthsMismatch(length, tokens.length, tos.length)
        );

        transferAmounts = new uint256[](length);

        for (uint256 i = 0; i < length; i++) {
            transferAmounts[i] = _executeAllowanceTransfer(safes[i], msg.sender, tokens[i], payable(tos[i]));
        }

        return transferAmounts;
    }

    /// @inheritdoc ILinearAllowanceSingleton
    function getTotalUnspent(address source, address delegate, address token) public view returns (uint256) {
        LinearAllowance memory allowance = allowances[source][delegate][token];
        uint256 newAccrued = _calculateNewAccrued(allowance);
        return allowance.totalUnspent + newAccrued;
    }

    /// @notice Get the token balance of a safe
    /// @param account Account address
    /// @param token Use NATIVE_TOKEN for ETH, otherwise ERC20 address
    /// @return balance Token balance in token base units
    function getBalance(address account, address token) public view returns (uint256 balance) {
        if (token == NATIVE_TOKEN) {
            balance = address(account).balance;
        } else {
            balance = IERC20(token).balanceOf(account);
        }
    }

    function getMaxWithdrawableAmount(address source, address delegate, address token) public view returns (uint256) {
        uint256 totalUnspent = getTotalUnspent(source, delegate, token);
        if (totalUnspent == 0) return 0;

        uint256 safeBalance = getBalance(source, token);

        return totalUnspent <= safeBalance ? totalUnspent : safeBalance;
    }

    /// @notice Internal function to set a single allowance
    /// @param safe Safe address setting the allowance
    /// @param delegate Authorized spender address
    /// @param token Use NATIVE_TOKEN for ETH, otherwise ERC20 address
    /// @param dripRatePerDay Drip rate in token base units per day
    function _setAllowance(address safe, address delegate, address token, uint192 dripRatePerDay) internal {
        // Cache storage struct in memory to save gas
        if (delegate == address(0)) revert AddressZeroForArgument("delegate");
        LinearAllowance memory a = allowances[safe][delegate][token];

        a = _calculateCurrentAllowance(a);
        a = _updateDripRatePerDay(a, dripRatePerDay);

        allowances[safe][delegate][token] = a;

        emit AllowanceSet(safe, delegate, token, dripRatePerDay);
    }

    /// @notice Internal function to revoke a single allowance
    /// @param safe Safe address revoking the allowance
    /// @param delegate Spender whose allowance is revoked
    /// @param token Use NATIVE_TOKEN for ETH, otherwise ERC20 address
    function _revokeAllowance(address safe, address delegate, address token) internal {
        if (delegate == address(0)) revert AddressZeroForArgument("delegate");

        LinearAllowance memory allowance = allowances[safe][delegate][token];
        allowance = _calculateCurrentAllowance(allowance);

        emit AllowanceRevoked(safe, delegate, token, allowance.totalUnspent);

        allowance = _updateDripRatePerDay(allowance, 0);
        allowance.totalUnspent = 0;

        allowances[safe][delegate][token] = allowance;
    }

    /// @notice Internal function to execute a single allowance transfer
    /// @param safe Safe address that owns the allowance
    /// @param delegate Authorized spender executing the transfer
    /// @param token Use NATIVE_TOKEN for ETH, otherwise ERC20 address
    /// @param to Recipient address
    /// @return transferAmount Amount transferred in token base units
    function _executeAllowanceTransfer(
        address safe,
        address delegate,
        address token,
        address payable to
    ) internal returns (uint256 transferAmount) {
        if (safe == address(0)) revert AddressZeroForArgument("safe");
        if (to == address(0)) revert AddressZeroForArgument("to");

        // Cache storage in memory (single SLOAD)
        LinearAllowance memory a = allowances[safe][delegate][token];

        // Calculate current allowance values
        a = _calculateCurrentAllowance(a);
        if (a.totalUnspent == 0) revert NoAllowanceToTransfer(safe, delegate, token);

        // Calculate transfer amount based on available allowance and safe balance
        transferAmount = getMaxWithdrawableAmount(safe, delegate, token);
        if (transferAmount == 0) revert ZeroTransfer(safe, delegate, token);

        // Update bookkeeping and write to storage BEFORE external calls (effects)
        a.totalSpent += transferAmount;
        a.totalUnspent -= transferAmount;
        allowances[safe][delegate][token] = a;

        emit AllowanceTransferred(safe, delegate, token, to, transferAmount);

        _executeTransfer(safe, delegate, token, to, transferAmount);

        return transferAmount;
    }

    /// @notice Execute a transfer from the safe to the recipient
    /// @dev Uses beneficiary balance to check if the transfer was successful; fee-charging tokens are not supported.
    /// @param safe Safe address executing the transfer
    /// @param delegate Spender executing transfer (for error reporting)
    /// @param token Use NATIVE_TOKEN for ETH, otherwise ERC20 address
    /// @param to Recipient address
    /// @param amount Amount to transfer in token base units
    function _executeTransfer(address safe, address delegate, address token, address to, uint256 amount) internal {
        uint256 beneficiaryPreBalance = getBalance(to, token);

        bool success;
        if (token == NATIVE_TOKEN) {
            success = ISafe(payable(safe)).execTransactionFromModule(to, amount, "", uint8(Enum.Operation.Call));
        } else {
            bytes memory data = abi.encodeCall(IERC20.transfer, (to, amount));
            success = ISafe(payable(safe)).execTransactionFromModule(token, 0, data, uint8(Enum.Operation.Call));
        }

        // Explicit success check for defense-in-depth
        if (!success) revert SafeTransactionFailed();

        // Maintain existing balance verification as primary security control
        uint256 beneficiaryPostBalance = getBalance(to, token);
        require(beneficiaryPostBalance - beneficiaryPreBalance >= amount, TransferFailed(safe, delegate, token));
    }

    function _updateDripRatePerDay(
        LinearAllowance memory a,
        uint192 dripRatePerDay
    ) internal view returns (LinearAllowance memory) {
        a.dripRatePerDay = dripRatePerDay;
        a.lastBookedAtInSeconds = block.timestamp.toUint64();
        return a;
    }

    function _calculateCurrentAllowance(LinearAllowance memory a) internal view returns (LinearAllowance memory) {
        uint256 newAccrued = _calculateNewAccrued(a);

        if (newAccrued > 0) {
            a.totalUnspent += newAccrued;
            a.lastBookedAtInSeconds = block.timestamp.toUint64();
        }

        return a;
    }

    function _calculateNewAccrued(LinearAllowance memory allowance) internal view returns (uint256) {
        if (allowance.lastBookedAtInSeconds == 0) {
            return 0;
        }

        uint256 timeElapsed = block.timestamp - allowance.lastBookedAtInSeconds;
        uint256 newAccrued = (timeElapsed * allowance.dripRatePerDay) / 1 days;

        return newAccrued;
    }
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.0;

import { BaseHealthCheck } from "src/strategies/periphery/BaseHealthCheck.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { IUniswapV2Router02 } from "@tokenized-strategy-periphery/interfaces/Uniswap/V2/IUniswapV2Router02.sol";
import { UniswapV3Swapper } from "src/strategies/periphery/UniswapV3Swapper.sol";
import { IStaking, ISkyCompounder } from "src/strategies/interfaces/ISky.sol";
import { USDC_MAINNET } from "src/constants.sol";

/**
 * @title Sky Compounder Strategy
 * @author [mil0x](https://github.com/mil0x); modified by [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Yearn v3 Strategy that autocompounds staking rewards and donates per BaseHealthCheck rules
 * @dev Integrates with Sky staking; supports UniswapV2/V3 for reward swaps, referral code, and MEV protection
 * @custom:origin https://github.com/mil0x/sky-compounder
 */
contract SkyCompounderStrategy is BaseHealthCheck, UniswapV3Swapper, ISkyCompounder {
    using SafeERC20 for ERC20;

    /// @notice Whether rewards should be claimed during harvest
    bool public claimRewards = true;

    /// @notice Use UniswapV3 (true) or UniswapV2 (false) to sell rewards
    bool public useUniV3;

    /// @notice Yearn referral code used by staking protocol
    uint16 public referral = 13425;

    /// @notice Minimum amount out for swaps (absolute units) for MEV protection
    uint256 public minAmountOut;

    /// @notice Sky Protocol staking contract address
    address public immutable staking;

    /// @notice Rewards token address distributed by staking contract
    address public immutable rewardsToken;

    address private constant UNIV2ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D; // Uniswap V2 router on Mainnet

    // choices for base
    address private constant USDS = 0xdC035D45d973E3EC169d2276DDab16f1e407384F;
    address private constant DAI = 0x6B175474E89094C44Da98b954EedeAC495271d0F;
    address private constant USDC = USDC_MAINNET;
    address private constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;

    /// @notice Minimum asset balance threshold to skip dust amounts (100 base units)
    uint256 private constant ASSET_DUST = 100;

    /**
     * @notice Constructs the Sky Compounder Strategy
     * @param _staking Sky Protocol staking contract address
     * @param _name Strategy share token name
     * @param _symbol Strategy share token symbol
     * @param _management Management address (can update params)
     * @param _keeper Keeper address (calls report)
     * @param _emergencyAdmin Emergency admin address
     * @param _donationAddress Dragon router address (receives profit shares)
     * @param _enableBurning True to enable dragon loss protection
     * @param _tokenizedStrategyAddress TokenizedStrategy implementation address
     * @dev Validates staking contract is not paused and uses USDS as staking token
     */
    constructor(
        address _staking,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    )
        BaseHealthCheck(
            USDS,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        )
    {
        require(IStaking(_staking).paused() == false, "paused");
        require(USDS == IStaking(_staking).stakingToken(), "!stakingToken");
        rewardsToken = IStaking(_staking).rewardsToken();
        staking = _staking;
        base = USDS;
        minAmountToSell = 50e18; // Set the min amount for the swapper to sell
    }

    /**
     * @notice Enable/disable reward claiming during harvest
     * @dev Can be disabled if rewards are paused or issues are detected upstream
     * @param _claimRewards True to claim rewards on harvest, false to skip
     */
    function setClaimRewards(bool _claimRewards) external onlyManagement {
        claimRewards = _claimRewards;
        emit ClaimRewardsUpdated(_claimRewards);
    }

    /**
     * @notice Configure UniswapV3 usage and pool fees for reward swaps
     * @param _useUniV3 True to use UniswapV3, false for UniswapV2
     * @param _rewardToBase Uniswap V3 fee for reward→base pool (ppm)
     * @param _baseToAsset Uniswap V3 fee for base→asset pool (ppm)
     */
    function setUseUniV3andFees(bool _useUniV3, uint24 _rewardToBase, uint24 _baseToAsset) external onlyManagement {
        useUniV3 = _useUniV3;
        if (useUniV3) {
            _setUniFees(rewardsToken, base, _rewardToBase);
            _setUniFees(base, address(asset), _baseToAsset);
        }
        emit UniV3SettingsUpdated(_useUniV3, _rewardToBase, _baseToAsset);
    }

    /**
     * @notice Set minimum rewardsToken amount to sell (skip small swaps)
     * @param _minAmountToSell Minimum amount to sell in asset base units
     */
    function setMinAmountToSell(uint256 _minAmountToSell) external onlyManagement {
        minAmountToSell = _minAmountToSell;
        emit MinAmountToSellUpdated(_minAmountToSell);
    }

    /**
     * @notice Set base token and optionally UniswapV3 usage/fees
     * @param _base Address of USDS, DAI, USDC, or WETH
     * @param _useUniV3 True to use UniswapV3, false for UniswapV2
     * @param _rewardToBase Fee for reward→base pool (ppm, only if _useUniV3)
     * @param _baseToAsset Fee for base→asset pool (ppm, only if _useUniV3)
     * @dev When enabling UniswapV3, fee params must be set to avoid failed swaps during harvest
     */
    function setBase(address _base, bool _useUniV3, uint24 _rewardToBase, uint24 _baseToAsset) external onlyManagement {
        if (_base == USDS) {
            base = USDS;
        } else if (_base == DAI) {
            base = DAI;
        } else if (_base == USDC) {
            base = USDC;
        } else if (_base == WETH) {
            base = WETH;
        } else {
            revert("!base in list");
        }

        useUniV3 = _useUniV3;

        if (_useUniV3) {
            _setUniFees(rewardsToken, base, _rewardToBase);
            _setUniFees(base, address(asset), _baseToAsset);
        }

        emit BaseTokenUpdated(_base, _useUniV3, _rewardToBase, _baseToAsset);
    }

    /**
     * @notice Set referral code for staking
     * @param _referral Referral code (uint16)
     */
    function setReferral(uint16 _referral) external onlyManagement {
        referral = _referral;
        emit ReferralUpdated(_referral);
    }

    /**
     * @notice Set minimum amount out for swaps (slippage/MEV protection)
     * @param _minAmountOut Minimum output amount in asset base units
     * @dev Use private RPC and set conservative thresholds to mitigate sandwich attacks
     */
    function setMinAmountOut(uint256 _minAmountOut) external onlyManagement {
        minAmountOut = _minAmountOut;
        emit MinAmountOutUpdated(_minAmountOut);
    }

    /**
     * @notice Returns available deposit limit for owner
     * @dev Returns 0 if staking is paused, otherwise unlimited (type(uint256).max)
     * @return Available deposit limit in asset base units
     */
    function availableDepositLimit(address /*_owner*/) public view override returns (uint256) {
        bool paused = IStaking(staking).paused();
        if (paused) return 0;
        return type(uint256).max;
    }

    /// @notice Returns strategy's idle asset balance
    /// @return Asset balance in asset base units
    function balanceOfAsset() public view returns (uint256) {
        return asset.balanceOf(address(this));
    }

    /// @notice Returns strategy's staked balance (staking receipt tokens)
    /// @return _amount Staked balance in staking token base units
    function balanceOfStake() public view returns (uint256 _amount) {
        return ERC20(staking).balanceOf(address(this));
    }

    /// @notice Returns strategy's unclaimed rewards token balance
    /// @return Rewards balance in rewards token base units
    function balanceOfRewards() public view returns (uint256) {
        return ERC20(rewardsToken).balanceOf(address(this));
    }

    /// @notice Returns strategy's earned but unclaimed rewards from staking
    /// @return Claimable rewards in rewards token base units
    function claimableRewards() public view returns (uint256) {
        return IStaking(staking).earned(address(this));
    }

    /**
     * @notice Deploys idle assets into Sky staking
     * @dev Checks allowance and stakes with referral code
     * @param _amount Amount to stake in asset base units
     */
    function _deployFunds(uint256 _amount) internal override {
        _checkAllowance(staking, address(asset), _amount);
        IStaking(staking).stake(_amount, referral);
    }

    /**
     * @notice Withdraws staked assets from Sky staking
     * @param _amount Amount to withdraw in asset base units
     */
    function _freeFunds(uint256 _amount) internal override {
        IStaking(staking).withdraw(_amount);
    }

    /**
     * @notice Harvests rewards, swaps to asset, and reports total assets
     * @dev Claims rewards if enabled, swaps via UniV2/V3, redeploys idle funds
     * @return _totalAssets Total strategy assets (idle + staked) in asset base units
     */
    function _harvestAndReport() internal override returns (uint256 _totalAssets) {
        if (claimRewards) {
            IStaking(staking).getReward();
            // MEV PROTECTION: Use setMinAmountOut() to configure slippage protection.
            // Strategy keepers should set appropriate minAmountOut values and use private RPCS to prevent sandwich attacks.
            uint256 rewardBalance = balanceOfRewards();
            if (rewardBalance > 0) {
                if (useUniV3) {
                    // UniV3
                    _swapFrom(rewardsToken, address(asset), rewardBalance, minAmountOut);
                } else {
                    // UniV2
                    _uniV2swapFrom(rewardsToken, address(asset), rewardBalance, minAmountOut);
                }
            }
        }

        uint256 balance = balanceOfAsset();
        if (TokenizedStrategy.isShutdown()) {
            _totalAssets = balance + balanceOfStake();
        } else {
            if (balance > ASSET_DUST && !IStaking(staking).paused()) {
                _deployFunds(balance);
            }
            _totalAssets = balanceOfStake() + balanceOfAsset();
        }
    }

    /**
     * @notice Executes UniswapV2 swap from one token to another
     * @dev Only swaps if _amountIn >= minAmountToSell
     * @param _from Token to swap from
     * @param _to Token to swap to
     * @param _amountIn Amount to swap in _from token base units
     * @param _minAmountOut Minimum output amount for slippage protection in _to token base units
     */
    function _uniV2swapFrom(address _from, address _to, uint256 _amountIn, uint256 _minAmountOut) internal {
        if (_amountIn >= minAmountToSell) {
            _checkAllowance(UNIV2ROUTER, _from, _amountIn);
            IUniswapV2Router02(UNIV2ROUTER).swapExactTokensForTokens(
                _amountIn,
                _minAmountOut,
                _getTokenOutPath(_from, _to),
                address(this),
                block.timestamp
            );
        }
    }

    /**
     * @notice Emergency withdrawal from staking (called during shutdown)
     * @dev Withdraws min of requested amount or staked balance
     * @param _amount Amount to attempt to withdraw in asset base units
     */
    function _emergencyWithdraw(uint256 _amount) internal override {
        _amount = _min(_amount, balanceOfStake());
        _freeFunds(_amount);
    }

    /**
     * @notice Constructs UniswapV2 swap path (direct or via base token)
     * @dev Returns 2-hop path if _tokenIn or _tokenOut is base, otherwise 3-hop via base
     * @param _tokenIn Token to swap from
     * @param _tokenOut Token to swap to
     * @return _path Array of token addresses for swap route
     */
    function _getTokenOutPath(
        address _tokenIn,
        address _tokenOut
    ) internal view virtual returns (address[] memory _path) {
        address _base = base;
        bool isBase = _tokenIn == _base || _tokenOut == _base;
        _path = new address[](isBase ? 2 : 3);
        _path[0] = _tokenIn;

        if (isBase) {
            _path[1] = _tokenOut;
        } else {
            _path[1] = _base;
            _path[2] = _tokenOut;
        }
    }

    /// @notice Returns minimum of two uint256 values
    /// @param a First value
    /// @param b Second value
    /// @return Minimum value
    function _min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }
}

