pragma solidity ^0.8.25;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { ISwapper } from "./interfaces/ISwapper.sol";
import { ITokenizedStrategy } from "./interfaces/ITokenizedStrategy.sol";
import { YieldForwarder, IRedeemable, IReportable } from "./YieldForwarder.sol";

/// @notice Minimal ERC4626 interface to read a strategy's underlying asset
interface IERC4626Asset {
    /// @notice Returns the address of the underlying asset
    function asset() external view returns (address);
}

/// @notice Minimal interface for ERC-4626 maxRedeem
/// @dev Defined inline here (rather than imported from YieldForwarder) so this
///      contract compiles standalone on develop while the matching base-class
///      interface declarations ship in the sibling forwarder PR. Once both PRs merge,
///      both copies are byte-for-byte identical.
interface IMaxRedeem {
    /// @notice Maximum shares redeemable by `owner` right now (ERC-4626)
    /// @param owner Address whose redeem headroom is queried
    /// @return maxShares Upper bound on shares redeemable by `owner`
    function maxRedeem(address owner) external view returns (uint256 maxShares);
}

/// @notice Minimal interface for ERC-4626 convertToAssets (floor rounding)
interface IConvertible {
    /// @notice Preview the assets returned for `shares`, rounded down (ERC-4626)
    /// @param shares Amount of shares to preview
    /// @return assets Assets that would be returned by redeem(), before fees/loss
    function convertToAssets(uint256 shares) external view returns (uint256 assets);
}

/**
 * @title SwappingYieldForwarder
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Extends YieldForwarder with an additional swap step before forwarding to the receiver.
 * @dev Inherits reportAndForward() from YieldForwarder (no-swap fallback) and adds
 *      reportSwapAndForward() which swaps via a pluggable ISwapper before forwarding.
 *
 *      This dual-mode design acts as a built-in circuit breaker: if the swap protocol
 *      is unavailable, the keeper simply calls the inherited non-swapping path instead.
 *
 *      CALL CHAIN (with swap):
 *      Keeper EOA -> reportSwapAndForward() -> strategy.report() -> profit shares
 *      minted to this contract -> redeem shares to self -> swap via ISwapper ->
 *      target asset forwarded to receiver
 *
 *      CALL CHAIN (without swap / fallback):
 *      Keeper EOA -> reportAndForward() [inherited] -> strategy.report() -> profit shares
 *      minted to this contract -> redeem shares directly to receiver
 *
 *      DESIGN:
 *      - Keeper-gated: only the designated keeper can trigger yield forwarding
 *      - Single-purpose: assets can only flow to the hardcoded receiver
 *      - Pluggable swap: ISwapper adapter handles DEX-specific logic; the adapter
 *        itself is settable by the vault's management() role so deeper pools or
 *        newer adapter versions can be adopted without redeploying the forwarder
 *      - Dual-mode: keeper picks swap vs no-swap path at call-time
 *      - Strategy is passed as a call-time parameter to avoid circular dependencies
 */
contract SwappingYieldForwarder is YieldForwarder {
    using SafeERC20 for IERC20;

    // ============================================
    // ERRORS
    // ============================================

    /// @notice Thrown when the swapper address is zero
    error InvalidSwapper();

    /// @notice Thrown when the target asset address is zero
    error InvalidTargetAsset();

    /// @notice Thrown when the vault address is zero
    error InvalidVault();

    /// @notice Thrown when a swapper-management function is called by a non-management address
    error OnlyVaultManagement();

    /// @notice Thrown when a swapper reports an output below the enforced minimum
    /// @param expected Minimum amount expected
    /// @param actual Amount actually reported
    error InsufficientSwapOutput(uint256 expected, uint256 actual);

    /// @notice Thrown when setMinSlippageBps is called with a value above MAX_BPS
    error InvalidSlippageBps();

    /// @notice Thrown when the caller's minAmountOut falls below the admin-set floor
    /// @param floor Required minimum (assetsIn * minSlippageBps / MAX_BPS)
    /// @param supplied The minAmountOut the keeper passed in
    error SlippageFloorTooLoose(uint256 floor, uint256 supplied);

    /// @notice Thrown when `reportSwapAndForward` is called past the caller-supplied deadline
    /// @param deadline The keeper-chosen expiry timestamp (seconds since epoch)
    /// @param blockTimestamp The block time at which the call landed
    error ExpiredDeadline(uint256 deadline, uint256 blockTimestamp);

    // ============================================
    // EVENTS
    // ============================================

    /// @notice Emitted when shares are redeemed, swapped to target asset, and forwarded
    /// @param strategy Address of the strategy whose shares were redeemed
    /// @param receiver Address that received the target assets
    /// @param shares Amount of shares redeemed
    /// @param assetsIn Amount of underlying assets redeemed (swap input)
    /// @param assetsOut Amount of target assets forwarded (swap output)
    event YieldSwappedAndForwarded(
        address indexed strategy,
        address indexed receiver,
        uint256 shares,
        uint256 assetsIn,
        uint256 assetsOut
    );

    /// @notice Emitted when the swap adapter is replaced by vault management
    /// @param oldSwapper The previous ISwapper implementation
    /// @param newSwapper The newly installed ISwapper implementation
    event SwapperUpdated(address indexed oldSwapper, address indexed newSwapper);

    /// @notice Emitted when the admin-set slippage floor is updated
    /// @param oldBps Previous floor (basis points of assetsIn)
    /// @param newBps New floor
    event MinSlippageBpsUpdated(uint16 oldBps, uint16 newBps);

    // ============================================
    // STATE
    // ============================================

    /// @notice The desired output token after swapping
    /// @dev Set once at construction, cannot be changed
    address public immutable targetAsset;

    /// @notice The governance source for this forwarder
    /// @dev Calls to vault.management() at swapper-management time authorize the caller.
    ///      In a 1:1 forwarder-to-vault deployment this is the tokenized strategy
    ///      whose profit shares flow through this forwarder; vault management is
    ///      the same multisig that already controls keeper/dragon-router rotation.
    address public immutable vault;

    /// @notice The swap adapter used to convert underlying -> target asset
    /// @dev Settable by vault.management() to pivot to a different adapter
    ///      (e.g. a new pool tier, a new DEX version) without redeploying.
    ISwapper public swapper;

    /// @notice Denominator for basis-point calculations (10_000 = 100%)
    uint16 public constant MAX_BPS = 10_000;

    /// @notice Floor on minAmountOut, denominated as basis points of assetsIn.
    /// @dev Set at construction so the deployment config explicitly chooses whether
    ///      the floor is active from the first report. A value of 0 is an intentional
    ///      opt-out for routes where management relies on the keeper's oracle-informed
    ///      minAmountOut instead of a near-parity floor.
    uint16 public minSlippageBps;

    // ============================================
    // MODIFIERS
    // ============================================

    /// @dev Restricts a call to the vault's management() address. Reading this at call
    ///      time (instead of caching a local admin) means rotation via the vault's
    ///      own two-step transfer (setPendingManagement / acceptManagement) is
    ///      picked up automatically.
    modifier onlyVaultManagement() {
        if (msg.sender != ITokenizedStrategy(vault).management()) revert OnlyVaultManagement();
        _;
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    /// @notice Creates a new SwappingYieldForwarder
    /// @param _receiver Address that will receive all forwarded assets
    /// @param _keeper Address authorized to call reportAndForward / reportSwapAndForward
    /// @param _targetAsset Address of the desired output token after swapping
    /// @param _swapper Initial ISwapper implementation for DEX routing
    /// @param _vault Vault contract whose management() controls swapper rotation
    /// @param _minSlippageBps Initial floor in basis points of assetsIn (0 disables)
    constructor(
        address _receiver,
        address _keeper,
        address _targetAsset,
        address _swapper,
        address _vault,
        uint16 _minSlippageBps
    ) YieldForwarder(_receiver, _keeper) {
        if (_targetAsset == address(0)) revert InvalidTargetAsset();
        if (_swapper == address(0)) revert InvalidSwapper();
        if (_vault == address(0)) revert InvalidVault();
        if (_minSlippageBps > MAX_BPS) revert InvalidSlippageBps();
        targetAsset = _targetAsset;
        swapper = ISwapper(_swapper);
        vault = _vault;
        minSlippageBps = _minSlippageBps;
    }

    // ============================================
    // EXTERNAL FUNCTIONS
    // ============================================

    /// @notice Replace the active swap adapter
    /// @dev Authorized by vault.management(). The new adapter must expose the
    ///      ISwapper pull-pattern semantic; the forwarder enforces its own
    ///      minAmountOut re-check inside reportSwapAndForward as a
    ///      defence-in-depth guard against a buggy adapter.
    /// @param _newSwapper New ISwapper implementation
    function setSwapper(address _newSwapper) external onlyVaultManagement {
        if (_newSwapper == address(0)) revert InvalidSwapper();
        emit SwapperUpdated(address(swapper), _newSwapper);
        swapper = ISwapper(_newSwapper);
    }

    /// @notice Update the slippage floor applied to the keeper's minAmountOut
    /// @dev Authorized by vault.management(). Passing 0 disables the floor.
    /// @param _bps New floor in basis points of assetsIn (max 10_000)
    function setMinSlippageBps(uint16 _bps) external onlyVaultManagement {
        if (_bps > MAX_BPS) revert InvalidSlippageBps();
        emit MinSlippageBpsUpdated(minSlippageBps, _bps);
        minSlippageBps = _bps;
    }

    /**
     * @notice Calls report() on the strategy, redeems profit shares, swaps the underlying
     *         asset to the target asset via the configured ISwapper, and forwards to the receiver
     * @dev The swap path: redeem to self -> approve swapper -> swapper.swap() -> receiver.
     *      The swapper enforces minAmountOut internally; the forwarder additionally
     *      re-checks the reported output against minAmountOut as defence-in-depth
     *      in case a future/buggy adapter forgets its own check.
     *
     *      If report() produces no profit shares, the function returns 0 without reverting.
     *      If redemption returns 0 assets, the function returns 0 without attempting a swap.
     *
     *      The caller MUST supply a fresh `deadline` (seconds since epoch).
     *      The underlying Uniswap V3 adapter uses `block.timestamp` as the router deadline,
     *      which always passes at inclusion and therefore adds no real time bound between
     *      the keeper's quote and settlement. Enforcing an explicit expiry at the forwarder
     *      prevents stale-slippage execution when a queued transaction lands in a later
     *      block against a moved market. There is no `0 = disabled` sentinel: keepers
     *      always pass `block.timestamp + buffer` at transaction assembly time.
     *
     * @param strategy Address of the strategy contract (must implement IReportable, IRedeemable, IERC20, IERC4626Asset)
     * @param maxLoss Maximum acceptable loss in basis points for the redemption
     * @param minAmountOut Minimum acceptable amount of target asset after swap (slippage protection)
     * @param deadline Unix timestamp (seconds) past which the call reverts with ExpiredDeadline
     * @return assetsOut Amount of target asset forwarded to receiver (0 if no profit shares)
     */
    function reportSwapAndForward(
        address strategy,
        uint256 maxLoss,
        uint256 minAmountOut,
        uint256 deadline
    ) external nonReentrant returns (uint256 assetsOut) {
        // Freshness check runs before any state-touching work so an expired
        // call fails cheaply and the keeper can retry with a fresh deadline.
        if (block.timestamp > deadline) revert ExpiredDeadline(deadline, block.timestamp);
        if (msg.sender != keeper) revert OnlyKeeper();

        IReportable(strategy).report();

        uint256 balance = IERC20(strategy).balanceOf(address(this));
        if (balance == 0) return 0;

        // Mirror reportAndForward's maxRedeem cap so the inner redeem cannot
        // revert when external vault liquidity tightens below the forwarder's
        // share balance. Residual shares stay at the forwarder until headroom recovers.
        uint256 shares = Math.min(balance, IMaxRedeem(strategy).maxRedeem(address(this)));
        if (shares == 0) return 0;

        // Mirror reportAndForward's zero-asset skip so a dust share balance on
        // a loss-impaired strategy (totalAssets < totalSupply) does not
        // roll back the report() above. The dust stays at the forwarder for a later
        // report once the imbalance resolves.
        if (IConvertible(strategy).convertToAssets(shares) == 0) return 0;

        // Redeem to this contract (not receiver) so we can swap first
        uint256 assetsIn = IRedeemable(strategy).redeem(shares, address(this), address(this), maxLoss);
        if (assetsIn == 0) {
            emit YieldSwappedAndForwarded(strategy, receiver, shares, 0, 0);
            return 0;
        }

        address assetIn = IERC4626Asset(strategy).asset();

        // Configured slippage floor: keeper's minAmountOut must be at least
        // `assetsIn * minSlippageBps / MAX_BPS`, normalized from `assetIn` decimals
        // into `targetAsset` decimals so mixed-decimal pairs (USDC 6 <-> USDS 18, etc.)
        // aren't silently bypassed or DoS'd. A constructor value of 0 disables the floor.
        // The 1:1 value assumption matches the documented use case (near-parity pairs:
        // stablecoin<>stablecoin, LST<>LST); admins must keep the floor at 0 for
        // non-parity pairs.
        uint16 floorBps = minSlippageBps;
        if (floorBps != 0) {
            uint8 inDecimals = IERC20Metadata(assetIn).decimals();
            uint8 outDecimals = IERC20Metadata(targetAsset).decimals();
            uint256 assetsInScaled = inDecimals >= outDecimals
                ? assetsIn / (10 ** (inDecimals - outDecimals))
                : assetsIn * (10 ** (outDecimals - inDecimals));
            uint256 floor = (assetsInScaled * floorBps) / MAX_BPS;
            if (minAmountOut < floor) revert SlippageFloorTooLoose(floor, minAmountOut);
        }

        // Approve swapper and execute swap to receiver. The swapper pulls
        // via transferFrom and returns any unused tokenIn before returning.
        ISwapper currentSwapper = swapper;
        IERC20(assetIn).forceApprove(address(currentSwapper), assetsIn);
        assetsOut = currentSwapper.swap(assetIn, targetAsset, assetsIn, minAmountOut, receiver);
        IERC20(assetIn).forceApprove(address(currentSwapper), 0);

        // Forwarder-side minAmountOut re-check, independent of the swapper's own
        // check. Catches an honest-but-buggy adapter whose swap() returns an
        // amountOut below the threshold without reverting.
        if (assetsOut < minAmountOut) revert InsufficientSwapOutput(minAmountOut, assetsOut);

        emit YieldSwappedAndForwarded(strategy, receiver, shares, assetsIn, assetsOut);
    }

    /// @inheritdoc YieldForwarder
    function _authorizeForwardToken() internal view override {
        if (msg.sender != keeper && msg.sender != ITokenizedStrategy(vault).management()) {
            revert OnlyVaultManagement();
        }
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.20;

import { BaseAllocationMechanism, AllocationConfig } from "src/mechanisms/BaseAllocationMechanism.sol";
import { TokenizedAllocationMechanism } from "src/mechanisms/TokenizedAllocationMechanism.sol";
import { ProperQF } from "src/mechanisms/voting-strategy/ProperQF.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

/**
 * @title Quadratic Voting Mechanism
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Implements quadratic funding using ProperQF algorithm
 * @dev Follows Yearn V3 proxy pattern with ProperQF voting strategy
 *
 *      QUADRATIC FUNDING:
 *      ═══════════════════════════════════
 *      - Cost of voting is quadratic: weight votes costs weight² power
 *      - Prevents whale dominance (expensive to cast many votes)
 *      - Benefits: Small contributors have proportionally more impact
 *
 *      VOTE COST EXAMPLES:
 *      - 10 votes costs 100 voting power (10²)
 *      - 20 votes costs 400 voting power (20²)
 *      - 100 votes costs 10,000 voting power (100²)
 *
 *      ONE-TIME VOTING:
 *      ⚠️  Users can only vote ONCE per proposal
 *      - Vote is final and cannot be changed
 *      - Cannot increase, decrease, or cancel vote
 *      - Additional deposits create new voting power for other proposals
 *      - UI must warn users before voting
 *
 *      VOTING POWER:
 *      - Normalized to 18 decimals regardless of asset decimals
 *      - Linear relationship: 1 asset = 1 voting power (after normalization)
 *      - Each deposit adds to cumulative voting power
 *
 * @custom:security One-time voting prevents manipulation via vote adjustments
 * @custom:security Quadratic cost reduces whale influence
 */
contract QuadraticVotingMechanism is BaseAllocationMechanism, ProperQF {
    // ============================================
    // ERRORS
    // ============================================
    error ZeroAddressCannotPropose();
    error OnlyForVotesSupported();
    error InsufficientVotingPowerForQuadraticCost();

    error AlreadyVoted(address voter, uint256 pid);

    // ============================================
    // STATE VARIABLES
    // ============================================

    /// @notice Tracks whether a voter has voted on a specific proposal
    /// @dev Maps pid → voter → hasVoted (prevents double voting)
    mapping(uint256 => mapping(address => bool)) public hasVoted;

    /**
     * @notice Initialize QuadraticVotingMechanism with configuration and alpha parameters
     * @dev Called by AllocationMechanismFactory during CREATE2 deployment
     *      Sets up ProperQF algorithm with specified alpha weighting
     * @param _implementation Address of shared TokenizedAllocationMechanism implementation
     * @param _config Configuration struct with mechanism parameters
     * @param _alphaNumerator Alpha numerator (dimensionless ratio, 0 to _alphaDenominator)
     * @param _alphaDenominator Alpha denominator (dimensionless ratio, must be > 0)
     */
    constructor(
        address _implementation,
        AllocationConfig memory _config,
        uint256 _alphaNumerator,
        uint256 _alphaDenominator
    ) BaseAllocationMechanism(_implementation, _config) {
        _setAlpha(_alphaNumerator, _alphaDenominator);
    }

    /**
     * @notice Hook to validate proposer authorization
     * @dev Only keeper or management addresses can create proposals
     *      Prevents spam and maintains curation quality
     * @param proposer Address attempting to create proposal
     * @return authorized True if proposer is keeper or management
     */
    function _beforeProposeHook(address proposer) internal view virtual override returns (bool) {
        if (proposer == address(0)) revert ZeroAddressCannotPropose();

        // Get keeper and management addresses from TokenizedAllocationMechanism
        address keeper = _tokenizedAllocation().keeper();
        address management = _tokenizedAllocation().management();

        // Allow if proposer is either keeper or management
        return proposer == keeper || proposer == management;
    }

    /**
     * @notice Hook to validate proposal exists
     * @param pid Proposal ID to validate
     * @return valid True if proposal exists
     */
    function _validateProposalHook(uint256 pid) internal view virtual override returns (bool) {
        return _proposalExists(pid);
    }

    /**
     * @notice Hook to authorize user registration
     * @dev Allows all users to register, including multiple signups
     *      Each signup adds voting power that can be used on un-voted proposals
     *
     *      IMPORTANT DESIGN CONSIDERATION:
     *      Pure quadratic voting (QV) should restrict to single signups to prevent
     *      double-spending of vote credits. However, quadratic funding (QF) variants
     *      allow multiple signups where users contribute their own funds to increase
     *      voting power. Derived contracts can override to enforce single-signup.
     * @return authorized True (all users can signup)
     */
    function _beforeSignupHook(address) internal virtual override returns (bool) {
        return true;
    }

    /**
     * @notice Hook to calculate voting power from deposit amount
     * @dev Normalizes asset amount to 18 decimals for consistent voting power
     *      1 token (in asset decimals) = 1 voting power (in 18 decimals)
     *
     *      NORMALIZATION EXAMPLES:
     *      - USDC (6 decimals): 1,000,000 (1 USDC) → 1e18 voting power
     *      - WETH (18 decimals): 1e18 (1 WETH) → 1e18 voting power
     *      - WBTC (8 decimals): 100,000,000 (1 WBTC) → 1e18 voting power
     * @param deposit Amount deposited in asset's native decimals
     * @return votingPower Normalized voting power in 18 decimals
     */
    function _getVotingPowerHook(
        address,
        uint256 deposit
    ) internal view virtual override returns (uint256 votingPower) {
        // Get asset decimals
        uint8 assetDecimals = IERC20Metadata(address(asset)).decimals();

        // Convert to 18 decimals for voting power
        if (assetDecimals == 18) {
            return deposit;
        } else if (assetDecimals < 18) {
            // Scale up: multiply by 10^(18 - assetDecimals)
            uint256 scaleFactor = 10 ** (18 - assetDecimals);
            return deposit * scaleFactor;
        } else {
            // Scale down: divide by 10^(assetDecimals - 18)
            uint256 scaleFactor = 10 ** (assetDecimals - 18);
            return deposit / scaleFactor;
        }
    }

    /**
     * @notice Internal helper to normalize token amount to 18 decimals
     * @dev Matches voting power normalization logic in _getVotingPowerHook
     * @param amount Token amount in asset's native decimals
     * @param assetDecimals Decimal places of the asset token
     * @return normalized Amount normalized to 18 decimals
     */
    function _normalizeToDecimals(uint256 amount, uint8 assetDecimals) internal pure returns (uint256 normalized) {
        if (assetDecimals == 18) {
            return amount;
        } else if (assetDecimals < 18) {
            // Scale up: multiply by 10^(18 - assetDecimals)
            uint256 scaleFactor = 10 ** (18 - assetDecimals);
            return amount * scaleFactor;
        } else {
            // Scale down: divide by 10^(assetDecimals - 18)
            uint256 scaleFactor = 10 ** (assetDecimals - 18);
            return amount / scaleFactor;
        }
    }

    /**
     * @notice Hook to process vote with quadratic cost and single-vote enforcement
     * @dev Implements quadratic voting: to cast W votes, you pay W² voting power
     *      Each voter can only vote ONCE per proposal (no adjustments)
     *
     *      QUADRATIC COST FORMULA:
     *      cost = weight × weight
     *
     *      EXAMPLES:
     *      - Cast 10 votes → costs 100 voting power
     *      - Cast 50 votes → costs 2,500 voting power
     *      - Cast 100 votes → costs 10,000 voting power
     *
     *      This makes whale attacks expensive while giving smaller voters
     *      proportionally more influence per token.
     * @param pid Proposal ID to vote on
     * @param voter Address casting the vote
     * @param choice Vote type (must be VoteType.For)
     * @param weight Number of votes to cast (dimensionless)
     * @param oldPower Voter's current voting power (in 18 decimals)
     * @return newPower Remaining voting power after quadratic cost deduction (in 18 decimals)
     * @custom:security Single-vote enforcement prevents manipulation via vote adjustments
     * @custom:security Reverts if voter already voted on this proposal
     */
    function _processVoteHook(
        uint256 pid,
        address voter,
        TokenizedAllocationMechanism.VoteType choice,
        uint256 weight,
        uint256 oldPower
    ) internal virtual override returns (uint256) {
        if (choice != TokenizedAllocationMechanism.VoteType.For) revert OnlyForVotesSupported();

        // Check if voter has already voted on this proposal
        if (hasVoted[pid][voter]) revert AlreadyVoted(voter, pid);

        // Quadratic cost: to vote with weight W, you pay W^2 voting power
        uint256 quadraticCost = weight * weight;

        if (quadraticCost > oldPower) revert InsufficientVotingPowerForQuadraticCost();

        // Use ProperQF's unchecked vote processing since we control the inputs
        // contribution = quadratic cost, voteWeight = actual vote weight
        // We know: quadraticCost = weight^2, so sqrt(quadraticCost) = weight (perfect square root relationship)
        _processVoteUnchecked(pid, quadraticCost, weight);

        // Mark that voter has voted on this proposal
        hasVoted[pid][voter] = true;

        // Return remaining voting power after quadratic cost
        return oldPower - quadraticCost;
    }

    /**
     * @notice Hook to check if proposal meets quorum threshold
     * @dev Quorum based on total funding (quadratic + linear components)
     *      Uses ProperQF formula: F_j = α×(sum_sqrt)² + (1-α)×sum_contributions
     * @param pid Proposal ID to check
     * @return meetsQuorum True if project funding ≥ quorum threshold
     */
    function _hasQuorumHook(uint256 pid) internal view virtual override returns (bool meetsQuorum) {
        // Get the project's funding metrics
        // getTally() returns: alpha-weighted quadratic funding + alpha-weighted linear funding
        (, , uint256 quadraticFunding, uint256 linearFunding) = getTally(pid);

        // Calculate total funding: both components are already alpha-weighted
        // F_j = α × (sum_sqrt)² + (1-α) × sum_contributions
        uint256 projectTotalFunding = quadraticFunding + linearFunding;

        // Project meets quorum if it has minimum funding threshold
        return projectTotalFunding >= _getQuorumShares();
    }

    /**
     * @notice Hook to convert proposal funding into allocation shares
     * @dev Returns total funding amount (quadratic + linear components)
     *      Both components are already alpha-weighted by ProperQF
     * @param pid Proposal ID
     * @return shares Total funding to allocate in share base units
     */
    function _convertVotesToShares(uint256 pid) internal view virtual override returns (uint256 shares) {
        // Get project funding metrics
        // getTally() returns: alpha-weighted quadratic funding + alpha-weighted linear funding
        (, , uint256 quadraticFunding, uint256 linearFunding) = getTally(pid);

        // Calculate total funding: both components are already alpha-weighted
        // F_j = α × (sum_sqrt)² + (1-α) × sum_contributions
        return quadraticFunding + linearFunding;
    }

    /// @notice Allow finalization once voting period ends
    function _beforeFinalizeVoteTallyHook() internal pure virtual override returns (bool) {
        return true;
    }

    /// @notice Get recipient address for proposal
    function _getRecipientAddressHook(uint256 pid) internal view virtual override returns (address) {
        TokenizedAllocationMechanism.Proposal memory proposal = _getProposal(pid);
        if (proposal.recipient == address(0)) revert TokenizedAllocationMechanism.InvalidRecipient(proposal.recipient);
        return proposal.recipient;
    }

    /// @notice Handle custom share distribution - returns false to use default minting
    /// @return handled False to indicate default minting should be used
    /// @return assetsTransferred 0 since no custom distribution is performed
    function _requestCustomDistributionHook(
        address,
        uint256
    ) internal pure virtual override returns (bool handled, uint256 assetsTransferred) {
        // Return false to indicate we want to use the default share minting in TokenizedAllocationMechanism
        // This allows the base implementation to handle the minting via _mint()
        return (false, 0);
    }

    // Note: _availableWithdrawLimit is now inherited from BaseAllocationMechanism
    // The default implementation enforces timelock and grace period boundaries

    /// @notice Calculate total assets including matching pool + user deposits for finalization
    /// @dev This snapshots the total asset balance in the contract during finalize
    /// @return Total assets available for allocation (matching pool + user signup deposits)
    function _calculateTotalAssetsHook() internal view virtual override returns (uint256) {
        // Return current asset balance of the contract
        // This includes both:
        // 1. Matching pool funds (pre-funded in setUp)
        // 2. User deposits from signups
        return asset.balanceOf(address(this));
    }

    /// @notice Get project funding breakdown for a proposal
    /// @param pid Proposal ID
    /// @return sumContributions Total contribution amounts
    /// @return sumSquareRoots Sum of square roots for quadratic calculation
    /// @return quadraticFunding Quadratic funding component
    /// @return linearFunding Linear funding component
    function getProposalFunding(
        uint256 pid
    )
        external
        view
        returns (uint256 sumContributions, uint256 sumSquareRoots, uint256 quadraticFunding, uint256 linearFunding)
    {
        if (!_validateProposalHook(pid)) revert TokenizedAllocationMechanism.InvalidProposal(pid);

        // Return zero funding for cancelled proposals
        if (_tokenizedAllocation().state(pid) == TokenizedAllocationMechanism.ProposalState.Canceled) {
            return (0, 0, 0, 0);
        }

        return getTally(pid);
    }

    /// @notice Set the alpha parameter for quadratic vs linear funding weighting
    /// @param newNumerator Numerator of new alpha value (dimensionless ratio)
    /// @param newDenominator Denominator of new alpha value (dimensionless ratio)
    /// @dev Alpha determines the ratio: F_j = α × (sum_sqrt)² + (1-α) × sum_contributions
    /// @dev Only callable by owner (inherited from BaseAllocationMechanism via TokenizedAllocationMechanism)
    function setAlpha(uint256 newNumerator, uint256 newDenominator) external {
        // Access control: only owner can modify alpha
        require(_tokenizedAllocation().owner() == msg.sender, "Only owner can set alpha");

        // Update alpha using ProperQF's internal function (validates constraints internally)
        _setAlpha(newNumerator, newDenominator);
    }

    /// @notice Calculate optimal alpha for 1:1 shares-to-assets ratio given fixed matching pool amount
    /// @param matchingPoolAmount Fixed amount of matching funds available (in token's native decimals)
    /// @param totalUserDeposits Total user deposits in the mechanism (in token's native decimals)
    /// @return optimalAlphaNumerator Calculated alpha numerator
    /// @return optimalAlphaDenominator Calculated alpha denominator
    /// @dev Internally normalizes amounts to 18 decimals to match quadratic/linear sum calculations
    function calculateOptimalAlpha(
        uint256 matchingPoolAmount,
        uint256 totalUserDeposits
    ) external view returns (uint256 optimalAlphaNumerator, uint256 optimalAlphaDenominator) {
        // Get asset decimals to normalize amounts
        uint8 assetDecimals = IERC20Metadata(address(asset)).decimals();

        // Normalize both amounts to 18 decimals to match quadratic/linear sums
        uint256 normalizedMatchingPool = _normalizeToDecimals(matchingPoolAmount, assetDecimals);
        uint256 normalizedUserDeposits = _normalizeToDecimals(totalUserDeposits, assetDecimals);

        return
            _calculateOptimalAlpha(
                normalizedMatchingPool,
                totalQuadraticSum(),
                totalLinearSum(),
                normalizedUserDeposits
            );
    }

    /**
     * @notice Reject ETH deposits to prevent permanent fund loss
     * @dev Overrides BaseAllocationMechanism's receive() function
     *      This mechanism only supports ERC20 tokens, not native ETH
     * @custom:security Prevents accidental ETH loss
     */
    receive() external payable override {
        revert("ETH not supported - use ERC20 tokens only");
    }
}

