pragma solidity ^0.8.20;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { TokenizedAllocationMechanism, IBaseAllocationStrategy } from "src/mechanisms/TokenizedAllocationMechanism.sol";

/**
 * @notice Configuration parameters for allocation mechanism initialization
 * @dev All timing parameters are in seconds
 */
struct AllocationConfig {
    /// @notice Underlying ERC20 asset token for deposits
    IERC20 asset;
    /// @notice Name for allocation mechanism shares (ERC20 metadata)
    string name;
    /// @notice Symbol for allocation mechanism shares (ERC20 metadata)
    string symbol;
    /// @notice Delay before voting begins after proposal creation
    /// @dev In seconds. Provides time for proposal review before voting starts
    uint256 votingDelay;
    /// @notice Duration of the voting period
    /// @dev In seconds. Time window during which users can cast votes
    uint256 votingPeriod;
    /// @notice Minimum voting power required for proposal to pass
    /// @dev In share units. Proposal needs >= quorumShares total votes to succeed
    uint256 quorumShares;
    /// @notice Delay before redemptions can begin after vote finalization
    /// @dev In seconds. Security buffer before funds can be withdrawn
    uint256 timelockDelay;
    /// @notice Duration of redemption window
    /// @dev In seconds. Time window during which shares can be redeemed
    uint256 gracePeriod;
    /// @notice Address that owns/controls the allocation mechanism
    /// @dev Typically the deployer. Has admin privileges
    address owner;
}

/**
 * @title Base Allocation Mechanism
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Abstract base for allocation/voting mechanisms using lightweight proxy pattern
 * @dev Follows Yearn V3 architecture: minimal proxy delegating to shared TokenizedAllocationMechanism
 *
 *      ARCHITECTURE PATTERN:
 *      ═══════════════════════════════════
 *      - Inheritors only implement custom hooks (no shared logic duplication)
 *      - Shared logic lives in TokenizedAllocationMechanism (implementation)
 *      - Each mechanism is a lightweight proxy with custom behavior via hooks
 *      - Delegatecall pattern: proxy storage, implementation logic
 *
 *      HOOK SYSTEM:
 *      ═══════════════════════════════════
 *      13 abstract hooks to implement:
 *
 *      Registration:
 *      - _beforeSignupHook: Allow/block user registration
 *      - _getVotingPowerHook: Calculate voting power on signup
 *
 *      Proposing:
 *      - _beforeProposeHook: Allow/block proposal creation
 *      - _validateProposalHook: Validate proposal exists
 *
 *      Voting:
 *      - _processVoteHook: Process vote and update voting power
 *      - _hasQuorumHook: Check if proposal reached quorum
 *
 *      Distribution:
 *      - _convertVotesToShares: Convert votes to vault shares
 *      - _getRecipientAddressHook: Get recipient for proposal
 *      - _requestCustomDistributionHook: Custom share distribution
 *
 *      Finalization:
 *      - _beforeFinalizeVoteTallyHook: Pre-finalization checks
 *
 *      Withdrawal:
 *      - _availableWithdrawLimit: Enforce timelock/grace period
 *
 *      Accounting:
 *      - _calculateTotalAssetsHook: Total assets including matching pools
 *
 *      LIFECYCLE:
 *      ═══════════════════════════════════
 *      1. Deploy: Constructor calls TokenizedAllocationMechanism.initialize()
 *      2. Registration: Users deposit assets and receive voting power
 *      3. Propose: Create proposals for funding allocation
 *      4. Vote: Users cast votes (Against/For/Abstain)
 *      5. Finalize: Tally votes, determine winning proposals
 *      6. Queue: Mint shares for successful proposals (after timelock)
 *      7. Redeem: Recipients redeem shares for assets (during grace period)
 *
 *      TIMELOCK & GRACE PERIOD:
 *      ═══════════════════════════════════
 *      - Timelock: Security delay before redemptions begin
 *      - Grace Period: Window during which redemptions are allowed
 *      - After grace period: Unredeemed shares become non-withdrawable
 *
 * @custom:security All hooks called via delegatecall from implementation
 * @custom:security onlySelf modifier prevents direct external calls to hooks
 */
abstract contract BaseAllocationMechanism is IBaseAllocationStrategy {
    // ---------- Immutable Storage ----------

    /// @notice Address of the shared TokenizedAllocationMechanism implementation
    address internal immutable tokenizedAllocationAddress;

    /// @notice Underlying asset for the allocation mechanism
    IERC20 internal immutable asset;

    // ---------- Events ----------

    /// @notice Emitted when the allocation mechanism is initialized
    event AllocationMechanismInitialized(
        address indexed implementation,
        address indexed asset,
        string name,
        string symbol
    );

    // ---------- Constructor ----------

    /// @notice Initializes the allocation mechanism with implementation and configuration
    /// @param _implementation Address of the TokenizedAllocationMechanism implementation
    /// @param _config Configuration parameters for the allocation mechanism
    constructor(address _implementation, AllocationConfig memory _config) {
        // Store immutable values
        tokenizedAllocationAddress = _implementation;
        asset = _config.asset;

        // Initialize the TokenizedAllocationMechanism storage via delegatecall
        (bool success, ) = _implementation.delegatecall(
            abi.encodeCall(
                TokenizedAllocationMechanism.initialize,
                (
                    _config.owner, // owner
                    _config.asset,
                    _config.name,
                    _config.symbol,
                    _config.votingDelay,
                    _config.votingPeriod,
                    _config.quorumShares,
                    _config.timelockDelay,
                    _config.gracePeriod
                )
            )
        );
        require(success, "Initialization failed");

        emit AllocationMechanismInitialized(_implementation, address(_config.asset), _config.name, _config.symbol);
    }

    // ============================================
    // ABSTRACT HOOKS - REGISTRATION
    // ============================================

    /**
     * @notice REQUIRED: Determines if a user can register
     * @dev Called before signup to implement access control
     *
     *      IMPLEMENTATION GUIDANCE:
     *      - Return true to allow registration
     *      - Return false to block (will revert signup)
     *      - Can check allowlists, blocklists, KYC status, etc.
     *
     *      COMMON PATTERNS:
     *      - Open: Always return true (permissionless)
     *      - Allowlist: Check mapping(address => bool) allowedUsers
     *      - Minimum deposit: Check deposit >= minimumAmount
     *
     * @param user Address attempting to register
     * @return allow True to allow registration, false to block
     */
    function _beforeSignupHook(address user) internal virtual returns (bool);

    /**
     * @notice REQUIRED: Determines if an address can create proposals
     * @dev Called before propose to implement proposer restrictions
     *
     *      IMPLEMENTATION GUIDANCE:
     *      - Return true to allow proposal creation
     *      - Return false to block (will revert)
     *      - Can check minimum voting power, specific roles, etc.
     *
     *      COMMON PATTERNS:
     *      - Open: Always return true
     *      - Minimum power: Check votingPower >= threshold
     *      - Registered only: Check user has deposited
     *
     * @param proposer Address attempting to create proposal
     * @return allow True to allow proposal, false to block
     */
    function _beforeProposeHook(address proposer) internal view virtual returns (bool);

    /**
     * @notice REQUIRED: Calculates voting power assigned on registration
     * @dev Called during signup to determine user's initial voting power
     *
     *      IMPLEMENTATION GUIDANCE:
     *      - Must return value > 0 for successful registration
     *      - Should be deterministic based on deposit amount
     *      - Consider manipulation resistance (flash loan protection)
     *
     *      COMMON PATTERNS:
     *      - Linear: power = deposit (1 token = 1 vote)
     *      - Quadratic: power = sqrt(deposit) (reduces whale influence)
     *      - Capped: power = min(deposit, maxPower)
     *      - Time-weighted: power = f(deposit, stakeDuration)
     *
     *      SECURITY CONSIDERATIONS:
     *      - Prevent flash loan manipulation (use checkpoints/locks)
     *      - Validate deposit amount > 0
     *      - Ensure calculation cannot overflow
     *
     * @param user Address registering (can be used for user-specific logic)
     * @param deposit Amount of underlying tokens deposited (in asset base units)
     * @return power Voting power to assign (0 = registration fails)
     */
    function _getVotingPowerHook(address user, uint256 deposit) internal view virtual returns (uint256);

    // ============================================
    // ABSTRACT HOOKS - PROPOSAL VALIDATION
    // ============================================

    /**
     * @notice REQUIRED: Validates that a proposal ID exists
     * @dev Called to verify proposal exists before operations
     *
     * @param pid Proposal ID to validate
     * @return valid True if proposal exists and is valid
     */
    function _validateProposalHook(uint256 pid) internal view virtual returns (bool);

    // ============================================
    // ABSTRACT HOOKS - VOTING
    // ============================================

    /**
     * @notice REQUIRED: Processes a vote and updates voting power
     * @dev Called when user casts a vote. Must update vote tallies and return updated voting power
     *
     *      IMPLEMENTATION GUIDANCE:
     *      - Record vote in proposal's tally
     *      - Deduct used voting power from voter's available power
     *      - Return new voting power (must be <= oldPower)
     *      - Prevent double voting or power overflow
     *
     *      VOTING MODELS:
     *      - One-time: Use full power once (newPower = 0)
     *      - Proportional: Deduct weight from power (newPower = oldPower - weight)
     *      - Quadratic: Deduct weight squared (cost increases with usage)
     *
     * @param pid Proposal ID being voted on
     * @param voter Address casting the vote
     * @param choice Vote type (Against=0, For=1, Abstain=2)
     * @param weight Amount of voting power to use
     * @param oldPower Voter's current voting power before this vote
     * @return newPower Voter's voting power after this vote (must be <= oldPower)
     */
    function _processVoteHook(
        uint256 pid,
        address voter,
        TokenizedAllocationMechanism.VoteType choice,
        uint256 weight,
        uint256 oldPower
    ) internal virtual returns (uint256 newPower);

    /**
     * @notice REQUIRED: Checks if proposal reached quorum
     * @dev Called to determine if proposal has enough votes to pass
     *
     * @param pid Proposal ID
     * @return hasQuorum True if proposal has sufficient votes
     */
    function _hasQuorumHook(uint256 pid) internal view virtual returns (bool);

    // ============================================
    // ABSTRACT HOOKS - DISTRIBUTION
    // ============================================

    /**
     * @notice REQUIRED: Converts votes to vault shares for winning proposal
     * @dev Called when queuing successful proposal. Determines funding allocation
     *
     *      COMMON PATTERNS:
     *      - Direct: shares = votes (1 vote = 1 asset)
     *      - Quadratic: shares = votes^2 (quadratic funding)
     *      - Matched: shares = votes + matching(votes)
     *
     * @param pid Proposal ID being queued
     * @return sharesToMint Vault shares to allocate (in share base units)
     */
    function _convertVotesToShares(uint256 pid) internal view virtual returns (uint256 sharesToMint);

    /**
     * @notice REQUIRED: Pre-finalization validation hook
     * @dev Called before finalizeVoteTally to enforce any custom rules
     *
     * @return allow True to proceed with finalization
     */
    function _beforeFinalizeVoteTallyHook() internal virtual returns (bool);

    /**
     * @notice REQUIRED: Returns recipient address for a proposal
     * @dev Called during redemption to determine where shares go
     *
     * @param pid Proposal ID
     * @return recipient Address to receive the minted shares
     */
    function _getRecipientAddressHook(uint256 pid) internal view virtual returns (address recipient);

    /**
     * @notice OPTIONAL: Custom distribution instead of standard share minting
     * @dev Called during queue. Return (true, amount) to skip default minting
     *
     *      USE CASES:
     *      - Direct asset transfer instead of shares
     *      - Multi-recipient distribution
     *      - Custom vesting schedules
     *
     *      DEFAULT BEHAVIOR:
     *      Return (false, 0) to use standard share minting
     *
     * @param recipient Address of the recipient
     * @param sharesToMint Number of shares to distribute
     * @return handled True if custom distribution performed (skips default minting)
     * @return assetsTransferred Amount of assets transferred (for totalAssets accounting)
     */
    function _requestCustomDistributionHook(
        address recipient,
        uint256 sharesToMint
    ) internal virtual returns (bool handled, uint256 assetsTransferred);

    /// @dev Hook to get the available withdraw limit for a share owner
    /// @dev Default implementation enforces timelock and grace period boundaries
    /// @dev Can be overridden for custom withdrawal limit logic
    /// @return limit Available withdraw limit (type(uint256).max for unlimited, 0 for blocked)
    function _availableWithdrawLimit(address /* shareOwner */) internal view virtual returns (uint256) {
        // Get the global redemption start time
        uint256 globalRedemptionStart = _getGlobalRedemptionStart();

        // If no global redemption time set (not finalized), no withdrawals allowed
        if (globalRedemptionStart == 0) {
            return 0;
        }

        // Check if still in timelock period
        if (block.timestamp < globalRedemptionStart) {
            return 0; // Cannot withdraw during timelock
        }

        // Check if grace period has expired
        uint256 gracePeriod = _getGracePeriod();
        if (block.timestamp > globalRedemptionStart + gracePeriod) {
            return 0; // Cannot withdraw after grace period expires
        }

        // Within valid redemption window - no limit
        return type(uint256).max;
    }

    /// @dev Hook to calculate total assets including any matching pools or custom logic
    /// @return totalAssets Total assets for this allocation mechanism
    function _calculateTotalAssetsHook() internal view virtual returns (uint256);

    // ---------- External Hook Functions (Yearn V3 Pattern) ----------
    // These are called by TokenizedAllocationMechanism via delegatecall
    // and use onlySelf modifier to ensure security

    /// @notice Ensures function can only be called via delegatecall from TokenizedAllocationMechanism
    /// @dev In delegatecall context, msg.sender is the proxy address (address(this)), not the caller
    modifier onlySelf() {
        // In delegatecall context, msg.sender must be address(this) to ensure
        // hooks can only be called via delegatecall from TokenizedAllocationMechanism
        require(msg.sender == address(this), "!self");
        _;
    }

    /// @notice External wrapper for _beforeSignupHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param user Address attempting to register
    /// @return allow True to allow registration, false to block
    function beforeSignupHook(address user) external onlySelf returns (bool) {
        return _beforeSignupHook(user);
    }

    /// @notice External wrapper for _beforeProposeHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param proposer Address attempting to create proposal
    /// @return allow True to allow proposal, false to block
    function beforeProposeHook(address proposer) external view onlySelf returns (bool) {
        return _beforeProposeHook(proposer);
    }

    /// @notice External wrapper for _getVotingPowerHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param user Address registering
    /// @param deposit Amount deposited in asset base units
    /// @return power Voting power to assign
    function getVotingPowerHook(address user, uint256 deposit) external view onlySelf returns (uint256) {
        return _getVotingPowerHook(user, deposit);
    }

    /// @notice External wrapper for _validateProposalHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param pid Proposal ID to validate
    /// @return valid True if proposal exists and is valid
    function validateProposalHook(uint256 pid) external view onlySelf returns (bool) {
        return _validateProposalHook(pid);
    }

    /// @notice External wrapper for _processVoteHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param pid Proposal ID being voted on
    /// @param voter Address casting the vote
    /// @param choice Vote type (0=Against, 1=For, 2=Abstain)
    /// @param weight Amount of voting power to use
    /// @param oldPower Voter's current voting power
    /// @return newPower Voter's voting power after this vote
    function processVoteHook(
        uint256 pid,
        address voter,
        uint8 choice,
        uint256 weight,
        uint256 oldPower
    ) external onlySelf returns (uint256) {
        return _processVoteHook(pid, voter, TokenizedAllocationMechanism.VoteType(choice), weight, oldPower);
    }

    /// @notice External wrapper for _hasQuorumHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param pid Proposal ID
    /// @return hasQuorum True if proposal has sufficient votes
    function hasQuorumHook(uint256 pid) external view onlySelf returns (bool) {
        return _hasQuorumHook(pid);
    }

    /// @notice External wrapper for _convertVotesToShares, called by TokenizedAllocationMechanism via delegatecall
    /// @param pid Proposal ID being queued
    /// @return sharesToMint Vault shares to allocate in share base units
    function convertVotesToShares(uint256 pid) external view onlySelf returns (uint256) {
        return _convertVotesToShares(pid);
    }

    /// @notice External wrapper for _beforeFinalizeVoteTallyHook, called by TokenizedAllocationMechanism via delegatecall
    /// @return allow True to proceed with finalization
    function beforeFinalizeVoteTallyHook() external onlySelf returns (bool) {
        return _beforeFinalizeVoteTallyHook();
    }

    /// @notice External wrapper for _getRecipientAddressHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param pid Proposal ID
    /// @return recipient Address to receive the minted shares
    function getRecipientAddressHook(uint256 pid) external view onlySelf returns (address) {
        return _getRecipientAddressHook(pid);
    }

    /// @notice External wrapper for _requestCustomDistributionHook, called by TokenizedAllocationMechanism via delegatecall
    /// @param recipient Address of the recipient
    /// @param sharesToMint Number of shares to distribute
    /// @return handled True if custom distribution performed
    /// @return assetsTransferred Amount of assets transferred
    function requestCustomDistributionHook(
        address recipient,
        uint256 sharesToMint
    ) external onlySelf returns (bool handled, uint256 assetsTransferred) {
        return _requestCustomDistributionHook(recipient, sharesToMint);
    }

    /// @notice External wrapper for _availableWithdrawLimit, called by TokenizedAllocationMechanism via delegatecall
    /// @param shareOwner Address to check withdraw limit for
    /// @return limit Available withdraw limit (type(uint256).max for unlimited, 0 for blocked)
    function availableWithdrawLimit(address shareOwner) external view onlySelf returns (uint256) {
        return _availableWithdrawLimit(shareOwner);
    }

    /// @notice External wrapper for _calculateTotalAssetsHook, called by TokenizedAllocationMechanism via delegatecall
    /// @return totalAssets Total assets for this allocation mechanism
    function calculateTotalAssetsHook() external view onlySelf returns (uint256) {
        return _calculateTotalAssetsHook();
    }

    // ---------- Internal Helpers ----------

    /// @notice Access TokenizedAllocationMechanism interface for internal calls
    /// @dev Uses current contract address since storage is local
    function _tokenizedAllocation() internal view returns (TokenizedAllocationMechanism) {
        return TokenizedAllocationMechanism(address(this));
    }

    /// @notice Get grace period from configuration
    /// @return Grace period in seconds
    function _getGracePeriod() internal view returns (uint256) {
        return _tokenizedAllocation().gracePeriod();
    }

    /// @dev Get global redemption start timestamp
    /// @return Timestamp when redemption window opens (0 if not finalized)
    function _getGlobalRedemptionStart() internal view returns (uint256) {
        return _tokenizedAllocation().globalRedemptionStart();
    }

    // ---------- Fallback Function ----------

    /// @notice Delegates all undefined function calls to TokenizedAllocationMechanism
    /// @dev This enables the proxy pattern where shared logic lives in the implementation
    fallback() external payable virtual {
        address _impl = tokenizedAllocationAddress;
        assembly {
            // Copy calldata to memory
            calldatacopy(0, 0, calldatasize())

            // Delegatecall to implementation contract
            let result := delegatecall(gas(), _impl, 0, calldatasize(), 0, 0)

            // Copy return data
            returndatacopy(0, 0, returndatasize())

            // Handle result
            switch result
            case 0 {
                // Delegatecall failed, revert with error data
                revert(0, returndatasize())
            }
            default {
                // Delegatecall succeeded, return data
                return(0, returndatasize())
            }
        }
    }

    /// @notice Receive function to accept ETH
    receive() external payable virtual {}

    // ---------- View Helpers for Inheritors ----------

    /// @notice Get the current proposal count
    /// @dev Helper for concrete implementations to access storage
    function _getProposalCount() internal view returns (uint256) {
        return _tokenizedAllocation().getProposalCount();
    }

    /// @notice Check if a proposal exists
    /// @dev Helper for concrete implementations
    function _proposalExists(uint256 pid) internal view returns (bool) {
        return pid > 0 && pid <= _getProposalCount();
    }

    /// @notice Get proposal details
    /// @dev Helper for concrete implementations
    function _getProposal(uint256 pid) internal view returns (TokenizedAllocationMechanism.Proposal memory) {
        return _tokenizedAllocation().proposals(pid);
    }

    /// @notice Get voting power for an address
    /// @dev Helper for concrete implementations
    function _getVotingPower(address user) internal view returns (uint256) {
        return _tokenizedAllocation().votingPower(user);
    }

    /// @notice Get quorum shares requirement
    /// @dev Helper for concrete implementations
    function _getQuorumShares() internal view returns (uint256) {
        return _tokenizedAllocation().quorumShares();
    }
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.25;

import { MultistrategyVault } from "src/core/MultistrategyVault.sol";
import { IMultistrategyVault } from "src/core/interfaces/IMultistrategyVault.sol";
import { IMultistrategyLockedVault } from "src/core/interfaces/IMultistrategyLockedVault.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title MultistrategyLockedVault
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice A locked vault with custody-based rage quit mechanism and two-step cooldown period changes
 *
 * @dev This vault implements a secure custody system that prevents rage quit cooldown bypass attacks
 * and provides user protection through a two-step governance process for cooldown period changes.
 *
 * ## Custody Mechanism:
 *
 * 1. **Share Locking During Rage Quit:**
 *    - Users must initiate rage quit for a specific number of shares
 *    - Those shares are placed in custody and cannot be transferred
 *    - Locked shares are tracked separately from the user's transferable balance
 *    - Transfer restrictions prevent bypassing the cooldown period
 *    - Only one active rage quit per user (no multiple concurrent rage quits)
 *
 * 2. **Custody Lifecycle:**
 *    - **Initiation**: User specifies exact number of shares to lock for rage quit
 *    - **Cooldown**: Shares remain locked and non-transferable during cooldown period
 *    - **Unlock**: After cooldown, user can withdraw/redeem up to their custodied amount
 *    - **Withdrawal**: Users can make multiple withdrawals from the same custody
 *    - **Completion**: Custody is cleared when all locked shares are withdrawn
 *
 * 3. **Transfer Restrictions:**
 *    - Users cannot transfer locked shares to other addresses
 *    - Available shares = total balance - locked shares
 *    - Prevents rage quit cooldown bypass through share transfers
 *    - Use `getTransferableShares()` to check available balance for transfers
 *
 * 4. **Withdrawal Rules:**
 *    - Users can only withdraw shares if they have active custody
 *    - Withdrawal amount cannot exceed remaining custodied shares
 *    - Multiple partial withdrawals are allowed from the same custody
 *    - New rage quit required after custody is fully withdrawn
 *    - `maxWithdraw()` and `maxRedeem()` return 0 if no custody or still in cooldown
 *
 * 5. **Utility Functions:**
 *    - `getTransferableShares(user)`: Returns shares available for transfer
 *    - `getRageQuitableShares(user)`: Returns shares available for rage quit initiation
 *    - `custodyInfo(user)`: Returns custody details (locked shares, unlock time)
 *
 * ## Two-Step Cooldown Period Changes:
 *
 * 1. **Grace Period Protection:**
 *    - Governance proposes cooldown period changes with 14-day delay
 *    - Users can rage quit under current terms during grace period
 *    - Protects users from unfavorable governance decisions
 *
 * 2. **Change Process:**
 *    - **Propose**: Governance proposes new period, starts grace period
 *    - **Grace Period**: 14 days for users to exit under current terms
 *    - **Finalize**: Anyone can finalize change after grace period
 *    - **Cancel**: Governance can cancel during grace period
 *
 * 3. **User Protection:**
 *    - Users who rage quit before finalization use old cooldown period
 *    - Users who rage quit after finalization use new cooldown period
 *    - No retroactive application of cooldown changes
 *
 * ## Governance:
 *
 * - **Regen Governance**: Has control over rage quit cooldown period changes
 * - **Direct Transfer**: Governance can be transferred immediately (no 2-step process)
 * - **Access Control**: Only regen governance can propose/cancel cooldown changes
 *
 * ## Example Scenarios:
 *
 * **Scenario A - Basic Custody Flow:**
 * 1. User has 1000 shares, initiates rage quit for 500 shares
 * 2. 500 shares locked in custody, 500 shares remain transferable
 * 3. `getTransferableShares(user)` returns 500, `getRageQuitableShares(user)` returns 0
 * 4. After cooldown, user can withdraw up to 500 shares
 * 5. User withdraws 300 shares, 200 shares remain in custody
 * 6. User can later withdraw remaining 200 shares without new rage quit
 *
 * **Scenario B - Two-Step Cooldown Change:**
 * 1. Current cooldown: 7 days, governance proposes 14 days
 * 2. Grace period: Users have 14 days to rage quit under 7-day terms
 * 3. User A rage quits during grace period → uses 7-day cooldown
 * 4. Change finalized after grace period
 * 5. User B rage quits after finalization → uses 14-day cooldown
 *
 * **Scenario C - Utility Function Usage:**
 * 1. User has 1000 shares, no active rage quit
 * 2. `getTransferableShares(user)` returns 1000
 * 3. `getRageQuitableShares(user)` returns 1000
 * 4. User initiates rage quit for 400 shares
 * 5. `getTransferableShares(user)` returns 600
 * 6. `getRageQuitableShares(user)` returns 0 (already has active rage quit)
 */
contract MultistrategyLockedVault is MultistrategyVault, IMultistrategyLockedVault {
    // ============================================
    // STATE VARIABLES
    // ============================================

    /// @notice Mapping of user addresses to their custody information
    /// @dev Tracks locked shares and unlock timestamp for each user's rage quit
    ///      Only one active custody per user (no concurrent rage quits)
    mapping(address => CustodyInfo) public custodyInfo;

    /// @notice Address of regen governance controlling rage quit parameters
    /// @dev Can propose/cancel rage quit cooldown period changes
    ///      Set during initialize() to the roleManager address
    address public regenGovernance;

    /// @notice Current active cooldown period for rage quits
    /// @dev In seconds. Applied to new rage quits when initiateRageQuit() is called
    ///      Can be changed via two-step process (propose + finalize after grace period)
    uint256 public rageQuitCooldownPeriod;

    /// @notice Pending new cooldown period awaiting finalization
    /// @dev Set to 0 when no change is pending. Non-zero indicates active proposal
    ///      Requires RAGE_QUIT_COOLDOWN_CHANGE_DELAY to elapse before finalization
    uint256 public pendingRageQuitCooldownPeriod;

    /// @notice Timestamp when current cooldown period change was proposed
    /// @dev Unix timestamp in seconds. Used to calculate grace period expiration
    ///      Set to 0 when no change is pending
    uint256 public rageQuitCooldownPeriodChangeTimestamp;

    // ============================================
    // CONSTANTS
    // ============================================

    /// @notice Initial rage quit cooldown period set at deployment
    /// @dev 7 days in seconds. Applied until governance changes it
    uint256 public constant INITIAL_RAGE_QUIT_COOLDOWN_PERIOD = 7 days;

    /// @notice Minimum allowed rage quit cooldown period
    /// @dev 1 day in seconds. Prevents cooldown from being set too short
    uint256 public constant RANGE_MINIMUM_RAGE_QUIT_COOLDOWN_PERIOD = 1 days;

    /// @notice Maximum allowed rage quit cooldown period
    /// @dev 30 days in seconds. Prevents cooldown from being set too long
    uint256 public constant RANGE_MAXIMUM_RAGE_QUIT_COOLDOWN_PERIOD = 30 days;

    /// @notice Grace period delay for cooldown changes
    /// @dev 14 days in seconds. Users have this time to rage quit under old terms
    uint256 public constant RAGE_QUIT_COOLDOWN_CHANGE_DELAY = 14 days;

    /**
     * @dev Modifier to restrict access to regen governance only
     * @custom:modifier Reverts with NotRegenGovernance if caller is not regen governance
     */
    modifier onlyRegenGovernance() {
        if (msg.sender != regenGovernance) revert NotRegenGovernance();
        _;
    }

    /**
     * @notice Initializes the locked vault with custody mechanism
     * @dev Extends MultistrategyVault.initialize() with custody features
     *
     *      INITIALIZATION:
     *      1. Sets initial rage quit cooldown to INITIAL_RAGE_QUIT_COOLDOWN_PERIOD (7 days)
     *      2. Calls parent initialize() for standard vault setup
     *      3. Sets _roleManager as regenGovernance address
     *
     *      DUAL ROLE:
     *      - _roleManager becomes both roleManager AND regenGovernance
     *      - roleManager: Controls vault roles (from parent)
     *      - regenGovernance: Controls rage quit parameters (this contract)
     *
     * @param _asset Address of underlying asset token (cannot be zero)
     * @param _name Human-readable vault token name
     * @param _symbol Vault token symbol ticker
     * @param _roleManager Address for role management AND regen governance
     * @param _profitMaxUnlockTime Profit unlock duration in seconds (0-31556952)
     * @custom:security Can only be called once per deployment
     */
    function initialize(
        address _asset,
        string memory _name,
        string memory _symbol,
        address _roleManager, // role manager is also the regen governance address
        uint256 _profitMaxUnlockTime
    ) public override(MultistrategyVault, IMultistrategyVault) {
        rageQuitCooldownPeriod = INITIAL_RAGE_QUIT_COOLDOWN_PERIOD;
        super.initialize(_asset, _name, _symbol, _roleManager, _profitMaxUnlockTime);
        regenGovernance = _roleManager;
    }

    /**
     * @notice Proposes a new rage quit cooldown period (step 1 of 2)
     * @dev Initiates two-step change process with grace period for user protection
     *
     *      VALIDATION:
     *      - Must be within valid range (1-30 days)
     *      - Must differ from current cooldown period
     *
     *      PROCESS:
     *      1. Validates new period is within allowed range
     *      2. Sets pendingRageQuitCooldownPeriod
     *      3. Records proposal timestamp
     *      4. Users have 14 days to rage quit under current terms
     *      5. After 14 days, anyone can finalize the change
     *
     * @param _rageQuitCooldownPeriod New cooldown period in seconds (86400-2592000, i.e., 1-30 days)
     * @custom:security Only callable by regenGovernance
     * @custom:security 14-day grace period protects users from unfavorable changes
     */
    function proposeRageQuitCooldownPeriodChange(uint256 _rageQuitCooldownPeriod) external onlyRegenGovernance {
        if (
            _rageQuitCooldownPeriod < RANGE_MINIMUM_RAGE_QUIT_COOLDOWN_PERIOD ||
            _rageQuitCooldownPeriod > RANGE_MAXIMUM_RAGE_QUIT_COOLDOWN_PERIOD
        ) {
            revert InvalidRageQuitCooldownPeriod();
        }

        if (_rageQuitCooldownPeriod == rageQuitCooldownPeriod) {
            revert InvalidRageQuitCooldownPeriod();
        }

        pendingRageQuitCooldownPeriod = _rageQuitCooldownPeriod;
        rageQuitCooldownPeriodChangeTimestamp = block.timestamp;

        uint256 effectiveTimestamp = block.timestamp + RAGE_QUIT_COOLDOWN_CHANGE_DELAY;
        emit PendingRageQuitCooldownPeriodChange(_rageQuitCooldownPeriod, effectiveTimestamp);
    }

    /**
     * @notice Finalizes the rage quit cooldown period change (step 2 of 2)
     * @dev Permissionless - anyone can call after grace period expires
     *
     *      REQUIREMENTS:
     *      - Must have pending change (pendingRageQuitCooldownPeriod != 0)
     *      - Grace period (14 days) must have elapsed
     *
     *      EFFECTS:
     *      - Updates rageQuitCooldownPeriod to pending value
     *      - Clears pending state
     *      - New rage quits use new cooldown period immediately
     */
    function finalizeRageQuitCooldownPeriodChange() external {
        if (pendingRageQuitCooldownPeriod == 0) {
            revert NoPendingRageQuitCooldownPeriodChange();
        }

        if (block.timestamp < rageQuitCooldownPeriodChangeTimestamp + RAGE_QUIT_COOLDOWN_CHANGE_DELAY) {
            revert RageQuitCooldownPeriodChangeDelayNotElapsed();
        }

        uint256 oldPeriod = rageQuitCooldownPeriod;
        rageQuitCooldownPeriod = pendingRageQuitCooldownPeriod;
        pendingRageQuitCooldownPeriod = 0;
        rageQuitCooldownPeriodChangeTimestamp = 0;

        emit RageQuitCooldownPeriodChanged(oldPeriod, rageQuitCooldownPeriod);
    }

    /**
     * @notice Cancels a pending rage quit cooldown period change
     * @dev Only callable during grace period (before finalization)
     *
     *      REQUIREMENTS:
     *      - Must have pending change
     *      - Grace period must NOT have elapsed yet
     *
     *      EFFECTS:
     *      - Clears all pending change state
     *      - Current cooldown period remains unchanged
     *
     * @custom:security Only callable by regenGovernance
     * @custom:security Cannot cancel after grace period expires
     */
    function cancelRageQuitCooldownPeriodChange() external onlyRegenGovernance {
        uint256 pending = pendingRageQuitCooldownPeriod;
        if (pending == 0) {
            revert NoPendingRageQuitCooldownPeriodChange();
        }

        uint256 proposedAt = rageQuitCooldownPeriodChangeTimestamp;
        if (block.timestamp >= proposedAt + RAGE_QUIT_COOLDOWN_CHANGE_DELAY) {
            revert RageQuitCooldownPeriodChangeDelayElapsed();
        }

        pendingRageQuitCooldownPeriod = 0;
        rageQuitCooldownPeriodChangeTimestamp = 0;

        emit RageQuitCooldownPeriodChangeCancelled(pending, proposedAt, block.timestamp);
        emit PendingRageQuitCooldownPeriodChange(0, 0);
    }

    /**
     * @notice Initiates rage quit by locking shares in custody
     * @dev Creates custody entry with current cooldown period
     *
     *      REQUIREMENTS:
     *      - shares > 0
     *      - shares <= user's balance
     *      - User must NOT have existing active custody
     *
     *      EFFECTS:
     *      - Locks specified shares (become non-transferable)
     *      - Sets unlock time = current timestamp + rageQuitCooldownPeriod
     *      - User can withdraw after unlock time
     *
     *      IMPORTANT:
     *      - Uses CURRENT cooldown period (not pending)
     *      - Locked shares cannot be transferred
     *      - Only one custody per user at a time
     *
     * @param shares Number of shares to lock for rage quit
     * @custom:security Reentrancy protected
     * @custom:security Prevents cooldown bypass via transfers
     */
    function initiateRageQuit(uint256 shares) external nonReentrant {
        if (shares == 0) revert InvalidShareAmount();
        uint256 userBalance = balanceOf(msg.sender);
        if (userBalance < shares) revert InsufficientBalance();

        CustodyInfo storage custody = custodyInfo[msg.sender];

        // Check if user already has shares in custody
        if (custody.lockedShares > 0) {
            revert RageQuitAlreadyInitiated();
        }

        // Lock the shares in custody
        custody.lockedShares = shares;
        custody.unlockTime = block.timestamp + rageQuitCooldownPeriod;

        emit RageQuitInitiated(msg.sender, shares, custody.unlockTime);
    }

    /**
     * @notice Cancels rage quit and releases custodied shares
     * @dev Clears custody, making all shares transferable again
     *
     *      REQUIREMENTS:
     *      - Must have active custody (lockedShares > 0)
     *
     *      EFFECTS:
     *      - Deletes entire custody entry
     *      - All shares become transferable
     *      - User can initiate new rage quit if desired
     */
    function cancelRageQuit() external {
        CustodyInfo storage custody = custodyInfo[msg.sender];

        if (custody.lockedShares == 0) {
            revert NoActiveRageQuit();
        }

        // Clear custody info
        uint256 freedShares = custody.lockedShares;
        delete custodyInfo[msg.sender];

        emit RageQuitCancelled(msg.sender, freedShares);
    }

    /**
     * @notice Override withdrawal functions to handle custodied shares
     */
    function withdraw(
        uint256 assets,
        address receiver,
        address owner,
        uint256 maxLoss,
        address[] calldata strategiesArray
    ) public override(MultistrategyVault, IMultistrategyVault) nonReentrant returns (uint256) {
        uint256 shares = _convertToShares(assets, Rounding.ROUND_UP);
        _processCustodyWithdrawal(owner, shares);
        _redeem(msg.sender, receiver, owner, assets, shares, maxLoss, strategiesArray);
        return shares;
    }

    /**
     * @notice Override redeem function to handle custodied shares
     */
    function redeem(
        uint256 shares,
        address receiver,
        address owner,
        uint256 maxLoss,
        address[] calldata strategiesArray
    ) public override(MultistrategyVault, IMultistrategyVault) nonReentrant returns (uint256) {
        _processCustodyWithdrawal(owner, shares);
        uint256 assets = _convertToAssets(shares, Rounding.ROUND_DOWN);
        // Always return the actual amount of assets withdrawn.
        return _redeem(msg.sender, receiver, owner, assets, shares, maxLoss, strategiesArray);
    }

    /**
     * @notice Set the regen governance address that can manage rage quit parameters
     * @param _regenGovernance New address to become regen governance
     * @dev Regen governance has exclusive control over:
     *      - Proposing rage quit cooldown period changes
     *      - Cancelling pending cooldown period changes
     * @custom:governance Only current regen governance can call this function
     */
    function setRegenGovernance(address _regenGovernance) external override onlyRegenGovernance {
        if (_regenGovernance == address(0)) revert InvalidGovernanceAddress();

        address oldGovernance = regenGovernance;
        regenGovernance = _regenGovernance;
        emit RegenGovernanceChanged(oldGovernance, _regenGovernance);
    }

    /**
     * @notice Process withdrawal of shares from custody during withdraw/redeem operations
     * @param owner Address of the share owner attempting withdrawal
     * @param shares Number of shares being withdrawn/redeemed
     * @dev Internal function that enforces custody withdrawal rules:
     *      - Owner must have active custody (lockedShares > 0)
     *      - Shares must still be locked (current time < unlockTime)
     *      - Withdrawal amount cannot exceed remaining custodied shares
     *      - Updates custody state by reducing locked shares
     *      - Clears custody when all locked shares are withdrawn
     * @custom:security Prevents unauthorized withdrawals and custody bypass
     */
    function _processCustodyWithdrawal(address owner, uint256 shares) internal {
        CustodyInfo storage custody = custodyInfo[owner];

        // Check if there are custodied shares
        if (custody.lockedShares == 0) {
            revert NoCustodiedShares();
        }

        // Ensure cooldown period has passed
        if (block.timestamp < custody.unlockTime) {
            revert SharesStillLocked();
        }

        // Ensure user has sufficient balance
        uint256 userBalance = balanceOf(owner);
        if (userBalance < shares) {
            revert InsufficientBalance();
        }

        // Can only withdraw up to locked amount
        if (shares > custody.lockedShares) {
            revert ExceedsCustodiedAmount();
        }

        // Reduce locked shares by withdrawn amount
        custody.lockedShares -= shares;

        // If all custodied shares withdrawn, reset custody info
        if (custody.lockedShares == 0) {
            delete custodyInfo[owner];
        }
    }

    /**
     * @notice Override ERC20 transfer to enforce custody transfer restrictions
     * @param sender_ Address attempting to send shares
     * @param receiver_ Address that would receive shares
     * @param amount_ Number of shares being transferred
     * @dev Implements custody-based transfer restrictions:
     *      - Calculates available shares (total balance - locked shares)
     *      - Prevents transfer if amount exceeds available shares
     *      - Allows normal transfers for non-custodied shares
     *      - Critical security feature preventing rage quit cooldown bypass
     * @custom:security Prevents users from bypassing cooldown by transferring locked shares
     */
    function _transfer(address sender_, address receiver_, uint256 amount_) internal override {
        // Check if sender has locked shares that would prevent this transfer
        CustodyInfo memory custody = custodyInfo[sender_];

        if (custody.lockedShares > 0) {
            uint256 senderBalance = balanceOf(sender_);
            uint256 availableShares = senderBalance - custody.lockedShares;

            // Revert if trying to transfer more than available shares
            if (amount_ > availableShares) {
                revert TransferExceedsAvailableShares();
            }
        }

        // Call parent implementation
        super._transfer(sender_, receiver_, amount_);
    }

    /// @inheritdoc IMultistrategyLockedVault
    function getPendingRageQuitCooldownPeriod() external view returns (uint256) {
        return pendingRageQuitCooldownPeriod;
    }

    /// @inheritdoc IMultistrategyLockedVault
    function getRageQuitCooldownPeriodChangeTimestamp() external view returns (uint256) {
        return rageQuitCooldownPeriodChangeTimestamp;
    }

    /**
     * @notice Get the maximum amount of assets that can be withdrawn by an owner
     * @param owner_ Address owning shares to check withdrawal limits for
     * @param maxLoss_ Custom max_loss if any
     * @param strategiesArray_ Custom strategies queue if any
     * @return Maximum amount of assets withdrawable
     * @dev This override accounts for custody constraints - returns 0 if:
     *      - Custody is still in cooldown period
     *      - Otherwise returns min of parent calculation and custodied shares in asset terms
     */
    function maxWithdraw(
        address owner_,
        uint256 maxLoss_,
        address[] calldata strategiesArray_
    ) external view override(MultistrategyVault, IMultistrategyVault) returns (uint256) {
        CustodyInfo memory custody = custodyInfo[owner_];
        if (block.timestamp < custody.unlockTime) {
            return 0;
        }

        // Get the max from parent implementation
        uint256 parentMax = _max_withdraw(owner_, maxLoss_, strategiesArray_);

        // Convert custodied shares to assets
        uint256 custodyAssets = _convertToAssets(custody.lockedShares, Rounding.ROUND_DOWN);

        // Return minimum of parent max and custody limit
        return Math.min(parentMax, custodyAssets);
    }

    /**
     * @notice Get the maximum amount of shares that can be redeemed by an owner
     * @param owner_ Address owning shares to check redemption limits for
     * @param maxLoss_ Custom max_loss if any
     * @param strategiesArray_ Custom strategies queue if any
     * @return Maximum amount of shares redeemable
     * @dev This override accounts for custody constraints - returns 0 if:
     *      - Custody is still in cooldown period
     *      - Otherwise returns min of balance and custodied shares
     */
    function maxRedeem(
        address owner_,
        uint256 maxLoss_,
        address[] calldata strategiesArray_
    ) external view override(MultistrategyVault, IMultistrategyVault) returns (uint256) {
        CustodyInfo memory custody = custodyInfo[owner_];

        if (block.timestamp < custody.unlockTime) {
            return 0;
        }

        // Get max shares from parent calculation
        uint256 parentMax = Math.min(
            _convertToShares(_max_withdraw(owner_, maxLoss_, strategiesArray_), Rounding.ROUND_DOWN),
            balanceOf(owner_)
        );

        // Get custody info to determine locked shares
        uint256 lockedShares = custody.lockedShares;

        // Return minimum of parent max and custody limit
        return Math.min(parentMax, lockedShares);
    }

    /**
     * @notice Get the amount of shares that can be transferred by a user
     * @param user Address to check transferable shares for
     * @return Amount of shares available for transfer (not locked in custody)
     * @dev Returns total balance minus shares currently locked in custody
     */
    function getTransferableShares(address user) external view returns (uint256) {
        uint256 totalShares = balanceOf(user);
        uint256 lockedShares = custodyInfo[user].lockedShares;
        return totalShares - lockedShares;
    }

    /**
     * @notice Get the amount of shares available for rage quit initiation
     * @param user Address to check rage quitable shares for
     * @return Amount of shares available for initiating rage quit
     * @dev Returns 0 if user already has active custody, otherwise returns full balance
     */
    function getRageQuitableShares(address user) external view returns (uint256) {
        // If user already has active custody, they cannot initiate new rage quit
        if (custodyInfo[user].lockedShares > 0) {
            return 0;
        }
        // Otherwise, they can rage quit all their shares
        return balanceOf(user);
    }
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.18;

import { IBaseStrategy } from "src/core/interfaces/IBaseStrategy.sol";
import { TokenizedStrategy, Math } from "src/core/TokenizedStrategy.sol";
import { WadRayMath } from "src/utils/libs/Maths/WadRay.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IYieldSkimmingStrategy } from "src/strategies/yieldSkimming/IYieldSkimmingStrategy.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title YieldSkimmingTokenizedStrategy
 * @author [Golem Foundation](https://golem.foundation)
 * @custom:security-contact security@golem.foundation
 * @notice Specialized TokenizedStrategy for yield-bearing assets with appreciating exchange rates.
 * @dev Mechanism:
 *      - Shares represent value-units of the underlying asset at the strategy exchange rate
 *        (1 share = 1 unit of underlying-asset value as returned by getCurrentExchangeRate)
 *        rather than raw asset amounts. Note: the underlying-asset value is NOT pegged to native ETH,
 *        even when the asset references stETH/wstETH/rETH — value follows the live exchange rate.
 *      - On report(), compares total vault value (assets * rate) vs total outstanding shares
 *        • Profit: mints dragon shares equal to excess value above total share debt
 *        • Loss: burns dragon shares (if enabled) up to available balance to cover shortfall
 *      - Insolvency determination: vault cannot cover user debt (excludes dragon shares as loss buffer)
 *      - Dual conversion modes:
 *        • Solvent: rate-based conversions using current exchange rate (RAY precision)
 *        • Insolvent: proportional distribution using base TokenizedStrategy logic
 *      - Dragon solvency protection: prevents dragon operations that would compromise user debt coverage
 *      - Dragon restrictions: cannot deposit/mint, cannot transfer to self, operations blocked during insolvency
 */
contract YieldSkimmingTokenizedStrategy is TokenizedStrategy {
    using Math for uint256;
    using WadRayMath for uint256;
    using SafeERC20 for ERC20;

    /// @dev Storage for yield skimming strategy
    struct YieldSkimmingStorage {
        uint256 totalDebtOwedToUserInAssetValue; // Track underlying-asset-value debt owed to users only
        uint256 lastReportedRate; // Track the last reported rate
        uint256 dragonRouterDebtInAssetValue; // Track the underlying-asset-value debt owed to dragon router
    }

    // ERC-7201 namespaced storage slot for yield-skimming state.
    // Formula: keccak256(abi.encode(uint256(keccak256(NAMESPACE)) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant YIELD_SKIMMING_STORAGE_SLOT =
        keccak256(abi.encode(uint256(keccak256("octant.yieldSkimming.exchangeRate")) - 1)) & ~bytes32(uint256(0xff));

    /// @dev Event emitted when harvest is performed
    event Harvest(address indexed caller, uint256 currentRate);

    /// @dev Events for donation tracking
    /// @param dragonRouter Address receiving or burning donation shares
    /// @param amount Amount of value-shares minted or burned (1 share = 1 value unit)
    /// @param exchangeRate Current exchange rate (scaled to wad) at the time of the event
    event DonationMinted(address indexed dragonRouter, uint256 amount, uint256 exchangeRate);
    /// @dev Emitted when dragon shares are burned to cover value losses
    event DonationBurned(address indexed dragonRouter, uint256 amount, uint256 exchangeRate);

    /**
     * @notice Deposit assets into the strategy with value debt tracking
     * @dev Requirements:
     *      - Vault must be solvent (reverts otherwise)
     *      - Receiver cannot be dragon router (dragon shares minted via report())
     *      - Tracks asset value debt
     * @param assets Amount of assets to deposit in asset base units
     * @param receiver Address to receive the shares (cannot be dragon router)
     * @return shares Amount of shares minted (1 share = 1 unit of underlying-asset value at the current rate)
     */
    function deposit(uint256 assets, address receiver) public virtual override nonReentrant returns (uint256 shares) {
        // Block deposits during vault insolvency
        _requireVaultSolvency();

        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();
        uint256 currentRate = _currentRateRay();

        // dragon router cannot deposit
        require(receiver != S.dragonRouter, "Dragon cannot deposit");

        if (YS.lastReportedRate == 0) {
            YS.lastReportedRate = currentRate;
        }

        // Deposit full balance if using max uint.
        if (assets == type(uint256).max) {
            assets = S.asset.balanceOf(msg.sender);
        }

        // Checking max deposit will also check if shutdown.
        require(assets <= _maxDeposit(S, receiver), "ERC4626: deposit more than max");

        // Issue shares based on value (1 share = 1 unit of underlying-asset value, except in case of uncovered loss)
        shares = assets.mulDiv(currentRate, WadRayMath.RAY);
        require(shares != 0, "ZERO_SHARES");

        // Update value debt
        YS.totalDebtOwedToUserInAssetValue += shares;

        // Call internal deposit to handle transfers and minting
        _deposit(S, receiver, assets, shares);

        return shares;
    }

    /**
     * @notice Mint exact shares from the strategy with value debt tracking
     * @dev Implements insolvency protection and tracks underlying-asset-value debt
     * @param shares Amount of shares to mint
     * @param receiver Address to receive the shares
     * @return assets Amount of assets deposited in asset base units (1 share = 1 unit of underlying-asset value, except in case of uncovered loss)
     */
    function mint(uint256 shares, address receiver) public virtual override nonReentrant returns (uint256 assets) {
        // Block mints during vault insolvency
        _requireVaultSolvency();

        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();

        // dragon router cannot mint
        require(receiver != S.dragonRouter, "Dragon cannot mint");

        uint256 currentRate = _currentRateRay();
        if (YS.lastReportedRate == 0) {
            YS.lastReportedRate = currentRate;
        }

        // Checking max mint will also check if shutdown
        require(shares <= _maxMint(S, receiver), "ERC4626: mint more than max");

        // Calculate assets needed based on value (1 share = 1 unit of underlying-asset value, except in case of uncovered loss)
        assets = shares.mulDiv(WadRayMath.RAY, currentRate, Math.Rounding.Ceil);
        require(assets != 0, "ZERO_ASSETS");

        // Update value debt
        YS.totalDebtOwedToUserInAssetValue += shares;

        // Call internal deposit to handle transfers and minting
        _deposit(S, receiver, assets, shares);

        return assets;
    }

    /**
     * @notice Redeem shares from the strategy with value debt tracking
     * @dev Shares represent underlying-asset value (1 share = 1 unit of underlying-asset value at the current rate, except in case of uncovered loss)
     * @param shares Amount of shares to redeem
     * @param receiver Address to receive the assets
     * @param owner Address whose shares are being redeemed
     * @param maxLoss Maximum acceptable loss in basis points
     * @return assets Amount of assets returned in asset base units
     */
    function redeem(
        uint256 shares,
        address receiver,
        address owner,
        uint256 maxLoss
    ) public override nonReentrant returns (uint256 assets) {
        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();

        // Burn stale dragon shares before pricing user exits to prevent dilution
        // by unburned junior capital during insolvency
        if (owner != S.dragonRouter) {
            _applyDragonLossProtectionIfNeeded(S, YS);
        }

        // Calculate actual value returned for debt tracking (before redemption)
        uint256 valueToReturn = shares; // 1 share = 1 unit of underlying-asset value, except in case of uncovered loss (regardless of actual assets received)

        // Validate inputs and check limits (replaces super.redeem validation)
        require(shares <= _maxRedeem(S, owner), "ERC4626: redeem more than max");
        require((assets = _convertToAssets(S, shares, Math.Rounding.Floor)) != 0, "ZERO_ASSETS");

        // Check if dragon redemption would compromise vault solvency
        _requireDragonSolvencyAfterOperation(owner, shares);

        assets = _withdraw(S, receiver, owner, assets, shares, maxLoss);

        // Update value debt after successful redemption (only for users)
        if (owner != S.dragonRouter) {
            YS.totalDebtOwedToUserInAssetValue = YS.totalDebtOwedToUserInAssetValue > valueToReturn
                ? YS.totalDebtOwedToUserInAssetValue - valueToReturn
                : 0;
        } else {
            YS.dragonRouterDebtInAssetValue = YS.dragonRouterDebtInAssetValue > valueToReturn
                ? YS.dragonRouterDebtInAssetValue - valueToReturn
                : 0;
        }

        // if vault is empty, reset all debts to 0
        if (_totalSupply(S) == 0) {
            YS.totalDebtOwedToUserInAssetValue = 0;
            YS.dragonRouterDebtInAssetValue = 0;
        }

        return assets;
    }

    /**
     * @notice Withdraw assets from the strategy with value debt tracking
     * @dev Calculates shares needed for the asset amount requested
     * @param assets Amount of assets to withdraw in asset base units
     * @param receiver Address to receive the assets
     * @param owner Address whose shares are being redeemed
     * @param maxLoss Maximum acceptable loss in basis points
     * @return shares Amount of shares burned in share base units
     */
    function withdraw(
        uint256 assets,
        address receiver,
        address owner,
        uint256 maxLoss
    ) public override nonReentrant returns (uint256 shares) {
        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();

        // Burn stale dragon shares before pricing user exits to prevent dilution
        // by unburned junior capital during insolvency
        if (owner != S.dragonRouter) {
            _applyDragonLossProtectionIfNeeded(S, YS);
        }

        // Validate inputs and check limits (replaces super.withdraw validation)
        require(assets <= _maxWithdraw(S, owner), "ERC4626: withdraw more than max");
        require((shares = _convertToShares(S, assets, Math.Rounding.Ceil)) != 0, "ZERO_SHARES");

        // Calculate actual value returned for debt tracking (before withdrawal)
        uint256 valueToReturn = shares; // 1 share = 1 unit of underlying-asset value

        // Check if dragon withdrawal would compromise vault solvency
        _requireDragonSolvencyAfterOperation(owner, shares);

        _withdraw(S, receiver, owner, assets, shares, maxLoss);

        // Update value debt after successful withdrawal (only for users)
        if (owner != S.dragonRouter) {
            YS.totalDebtOwedToUserInAssetValue = YS.totalDebtOwedToUserInAssetValue > valueToReturn
                ? YS.totalDebtOwedToUserInAssetValue - valueToReturn
                : 0;
        } else {
            YS.dragonRouterDebtInAssetValue = YS.dragonRouterDebtInAssetValue > valueToReturn
                ? YS.dragonRouterDebtInAssetValue - valueToReturn
                : 0;
        }

        // if vault is empty, reset all debts to 0
        if (_totalSupply(S) == 0) {
            YS.totalDebtOwedToUserInAssetValue = 0;
            YS.dragonRouterDebtInAssetValue = 0;
        }

        return shares;
    }

    /**
     * @notice Get the maximum amount of assets that can be deposited by a user
     * @dev Returns 0 for dragon router as they cannot deposit
     * @param receiver Address that would receive the shares
     * @return Maximum deposit amount in asset base units
     */
    function maxDeposit(address receiver) public view virtual override returns (uint256) {
        StrategyData storage S = _strategyStorage();
        if (_currentRateRay() == 0) {
            return 0;
        }
        if (receiver == S.dragonRouter || _isVaultInsolvent()) {
            return 0;
        }
        return super.maxDeposit(receiver);
    }

    /**
     * @notice Get the maximum amount of shares that can be minted by a user
     * @dev Returns 0 for dragon router as they cannot mint
     * @param receiver Address that would receive the shares
     * @return Maximum mint amount in shares
     */
    function maxMint(address receiver) public view virtual override returns (uint256) {
        StrategyData storage S = _strategyStorage();
        if (_currentRateRay() == 0) {
            return 0;
        }
        if (receiver == S.dragonRouter || _isVaultInsolvent()) {
            return 0;
        }
        return super.maxMint(receiver);
    }

    /**
     * @notice Get the maximum amount of assets that can be withdrawn by a user
     * @dev Dragon router has restrictions based on solvency protection to ensure user debt coverage.
     *      For non-dragon users during insolvency, simulates the lazy dragon burn that will occur
     *      in withdraw() to return the correct post-burn amount (ERC4626 compliance).
     * @param owner Address whose shares would be burned
     * @return Maximum withdraw amount in asset base units
     */
    function maxWithdraw(address owner) public view override returns (uint256) {
        StrategyData storage S = _strategyStorage();

        uint256 baseMaxWithdraw = super.maxWithdraw(owner);

        // Apply dragon-specific restrictions
        if (owner == S.dragonRouter) {
            uint256 dragonMaxRedeemShares = _maxDragonRedeemableShares();

            uint256 dragonMaxWithdrawAssets = _convertToAssets(S, dragonMaxRedeemShares, Math.Rounding.Floor);
            return Math.min(dragonMaxWithdrawAssets, baseMaxWithdraw);
        }

        // Simulate the lazy burn that withdraw() will perform to reflect post-burn pricing.
        // Without this, maxWithdraw underreports because _convertToAssets uses totalSupply
        // that still includes dragon shares (which the lazy burn will remove).
        uint256 burnAmount = _simulateDragonBurnAmount();
        if (burnAmount > 0) {
            uint256 postBurnSupply = _totalSupply(S) - burnAmount;
            if (postBurnSupply == 0) return 0;

            uint256 ownerShares = _balanceOf(S, owner);
            return ownerShares.mulDiv(S.totalAssets, postBurnSupply, Math.Rounding.Floor);
        }

        return baseMaxWithdraw;
    }

    /**
     * @notice Get the maximum amount of shares that can be redeemed by a user
     * @dev Dragon router has restrictions based on solvency protection to ensure user debt coverage.
     *      For non-dragon users, super.maxRedeem returns _balanceOf(owner) because
     *      availableWithdrawLimit is uncapped — no burn simulation needed here.
     * @param owner Address whose shares would be burned
     * @return Maximum redeem amount in shares
     */
    function maxRedeem(address owner) public view override returns (uint256) {
        StrategyData storage S = _strategyStorage();

        uint256 baseMaxRedeem = super.maxRedeem(owner);

        // Apply dragon-specific restrictions
        if (owner == S.dragonRouter) {
            uint256 dragonMaxRedeem = _maxDragonRedeemableShares();
            return Math.min(baseMaxRedeem, dragonMaxRedeem);
        }

        return baseMaxRedeem;
    }

    /**
     * @notice Get the total underlying-asset-value debt owed to users
     * @return Total user debt in underlying-asset value units
     */
    function gettotalDebtOwedToUserInAssetValue() external view returns (uint256) {
        return _strategyYieldSkimmingStorage().totalDebtOwedToUserInAssetValue;
    }

    /**
     * @notice Get the total underlying-asset-value debt owed to dragon router
     * @return Total dragon router debt in underlying-asset value units
     */
    function getDragonRouterDebtInAssetValue() external view returns (uint256) {
        return _strategyYieldSkimmingStorage().dragonRouterDebtInAssetValue;
    }

    /**
     * @notice Get the total underlying-asset-value debt owed to both users and dragon router combined
     * @return Total debt in underlying-asset value units combining users and dragon router
     */
    function getTotalValueDebtInAssetValue() external view returns (uint256) {
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();
        return YS.totalDebtOwedToUserInAssetValue + YS.dragonRouterDebtInAssetValue;
    }

    /**
     * @notice Preview the shares that would be minted for a deposit of `assets`.
     * @dev Returns 0 when the vault is insolvent or the exchange rate is 0. The real
     *      `deposit` path reverts via `_requireVaultSolvency`, so an inherited preview
     *      would lie to ERC-4626 integrators that expect `previewDeposit` to match the
     *      call they are about to make. In the solvent branch the inherited
     *      `_convertToShares` override already uses the same rate-based math as
     *      `deposit`, so delegating to `super.previewDeposit` is accurate.
     * @param assets Amount of assets hypothetically deposited
     * @return shares Shares a depositor would receive (0 when a real deposit would revert)
     */
    function previewDeposit(uint256 assets) public view virtual override returns (uint256 shares) {
        if (_currentRateRay() == 0 || _isVaultInsolvent()) return 0;
        return super.previewDeposit(assets);
    }

    /**
     * @notice Preview the assets required to mint exactly `shares`.
     * @dev Mirror of `previewDeposit`: returns 0 when the real `mint` path would revert
     *      (vault insolvent or exchange rate missing). Solvent branch uses the same
     *      Ceil-rounded conversion as `mint`.
     * @param shares Amount of shares hypothetically minted
     * @return assets Assets a minter would deposit (0 when a real mint would revert)
     */
    function previewMint(uint256 shares) public view virtual override returns (uint256 assets) {
        if (_currentRateRay() == 0 || _isVaultInsolvent()) return 0;
        return super.previewMint(shares);
    }

    /**
     * @notice Preview the shares burned to withdraw `assets`.
     * @dev The real `withdraw` path applies the lazy dragon burn before pricing the
     *      exit, so the post-burn `totalSupply` is the correct denominator in the
     *      insolvent branch. Simulate that burn via `_simulateDragonBurnAmount` and
     *      mirror the parent pro-rata math (Ceil rounding) against the reduced supply.
     *      When no burn is pending, the inherited `_convertToShares` override already
     *      matches `withdraw`, so `super.previewWithdraw` is accurate.
     * @param assets Amount of assets hypothetically withdrawn
     * @return shares Shares that would be burned (reflects pending dragon burn)
     */
    function previewWithdraw(uint256 assets) public view virtual override returns (uint256 shares) {
        uint256 burnAmount = _simulateDragonBurnAmount();
        if (burnAmount == 0) return super.previewWithdraw(assets);

        StrategyData storage S = _strategyStorage();
        if (S.totalAssets == 0) return 0;
        uint256 postBurnSupply = _totalSupply(S) - burnAmount;
        return assets.mulDiv(postBurnSupply, S.totalAssets, Math.Rounding.Ceil);
    }

    /**
     * @notice Preview the assets returned for redeeming `shares`.
     * @dev Mirror of `previewWithdraw`. Dragon-share burning never changes `totalAssets`
     *      or `totalDebtOwedToUserInAssetValue`, so `_isVaultInsolvent` stays true after
     *      the simulated burn and the parent pro-rata branch is the one that will fire
     *      in `redeem`. Floor rounding matches `redeem`'s `_convertToAssets` call.
     *      The preview is owner-agnostic by ERC-4626 shape; it models the non-dragon
     *      redemption path because that is where the lazy burn applies. Dragon-owner
     *      redemptions use `maxRedeem` for sizing, which already has its own override.
     * @param shares Amount of shares hypothetically redeemed
     * @return assets Assets a redeemer would receive (reflects pending dragon burn)
     */
    function previewRedeem(uint256 shares) public view virtual override returns (uint256 assets) {
        uint256 burnAmount = _simulateDragonBurnAmount();
        if (burnAmount == 0) return super.previewRedeem(shares);

        StrategyData storage S = _strategyStorage();
        uint256 postBurnSupply = _totalSupply(S) - burnAmount;
        if (postBurnSupply == 0) return 0;
        return shares.mulDiv(S.totalAssets, postBurnSupply, Math.Rounding.Floor);
    }

    /**
     * @notice Transfer shares with dragon solvency protection and debt rebalancing
     * @dev Special behaviors for dragon router:
     *      - Dragon cannot transfer to itself (reverts)
     *      - Dragon transfers trigger solvency checks to prevent user debt undercoverage
     *      - Transfers blocked if they would make vault unable to cover user debt
     *      - Dragon-involved transfers rebalance debt tracking (sender loses debt, receiver gains it)
     *      For non-dragon transfers, behaves like standard ERC20 transfer
     * @param to Address receiving shares
     * @param amount Amount of shares to transfer
     * @return success Whether the transfer succeeded
     */
    function transfer(address to, uint256 amount) external override returns (bool success) {
        StrategyData storage S = _strategyStorage();

        // Prevent dragon router from transferring to itself
        if (msg.sender == S.dragonRouter && to == S.dragonRouter) {
            revert("Dragon cannot transfer to itself");
        }

        _requireDragonSolvencyAfterOperation(msg.sender, amount);

        // Handle debt rebalancing when dragon is involved
        if (msg.sender == S.dragonRouter || to == S.dragonRouter) {
            _rebalanceDebtOnDragonTransfer(msg.sender, to, amount);
        }

        // Use base contract logic for actual transfer
        _transfer(S, msg.sender, to, amount);

        return true;
    }

    /**
     * @notice Transfer shares from one address to another with dragon solvency protection and debt rebalancing
     * @dev Special behaviors for dragon router:
     *      - Dragon cannot transfer to itself (reverts)
     *      - Dragon transfers trigger solvency checks to prevent user debt undercoverage
     *      - Transfers blocked if they would make vault unable to cover user debt
     *      - Dragon-involved transfers rebalance debt tracking (sender loses debt, receiver gains it)
     *      For non-dragon transfers, behaves like standard ERC20 transferFrom
     * @param from Address transferring shares
     * @param to Address receiving shares
     * @param amount Amount of shares to transfer
     * @return success Whether the transfer succeeded
     */
    function transferFrom(address from, address to, uint256 amount) external override returns (bool success) {
        StrategyData storage S = _strategyStorage();

        // Prevent dragon router from transferring to itself
        if (from == S.dragonRouter && to == S.dragonRouter) {
            revert("Dragon cannot transfer to itself");
        }

        _requireDragonSolvencyAfterOperation(from, amount);

        // Handle debt rebalancing when dragon is involved
        if (from == S.dragonRouter || to == S.dragonRouter) {
            _rebalanceDebtOnDragonTransfer(from, to, amount);
        }

        // Use base contract logic for actual transfer
        _spendAllowance(S, from, msg.sender, amount);
        _transfer(S, from, to, amount);

        return true;
    }

    /**
     * @notice Reports yield skimming strategy performance and handles profit distribution and loss coverage
     * @dev Overrides report to handle yield appreciation and loss recovery through dragon share minting/burning.
     *
     * Health check effectiveness depends on report() frequency. Exchange rate checks
     * become less effective over time if reports are infrequent, as profit limits may be exceeded.
     * Management should ensure regular reporting or adjust profit/loss ratios based on expected frequency.
     *
     * Key behaviors:
     * 1. **Value Comparison**: Compares current total value (assets * exchange rate) vs total outstanding shares
     * 2. **Profit Capture**: When current value exceeds total shares, mints dragon shares equal to excess value
     * 3. **Loss Protection**: When current value is less than total shares, burns dragon shares (if enabled) to cover shortfall
     * 4. **Insolvency Handling**: If dragon buffer insufficient for losses, remaining shortfall is handled through proportional asset distribution during withdrawals
     *
     * Event semantics: the `loss` value emitted via `Reported` is a gross
     * shortfall — the full gap between total value debt and current vault
     * value at the time of the call — not an incremental delta since the last
     * report. If `report()` is called multiple times during the same impairment
     * (e.g. dragon shares cannot fully cover the loss), the same gross shortfall
     * is re-emitted on each call.
     *
     * Integrators must not naively sum `loss` across consecutive `Reported`
     * events to compute cumulative damage; doing so double-counts persistent
     * impairments. Treat the event as a level signal, not a delta signal.
     *
     * @return profit Profit in assets from underlying value appreciation since the last report
     * @return loss Loss in assets — gross shortfall (level), not a delta. See event semantics above.
     */
    function report()
        public
        override(TokenizedStrategy)
        nonReentrant
        onlyKeepers
        returns (uint256 profit, uint256 loss)
    {
        StrategyData storage S = super._strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();

        // Update total assets from harvest
        uint256 currentTotalAssets = IBaseStrategy(address(this)).harvestAndReport();

        uint256 totalAssetsBalance = S.asset.balanceOf(address(this));
        if (totalAssetsBalance != currentTotalAssets) {
            S.totalAssets = totalAssetsBalance;
        }

        uint256 currentRate = _currentRateRay();
        uint256 totalAssets = totalAssetsBalance;
        uint256 currentValue = totalAssets.mulDiv(currentRate, WadRayMath.RAY);
        // Compare current value to total debt (user debt + dragon router debt combined)

        if (currentValue > YS.totalDebtOwedToUserInAssetValue + YS.dragonRouterDebtInAssetValue) {
            // Yield captured! Mint profit shares to dragon
            uint256 profitValue = currentValue - YS.totalDebtOwedToUserInAssetValue - YS.dragonRouterDebtInAssetValue;

            uint256 profitShares = profitValue; // 1 share = 1 unit of underlying-asset value, except in case of uncovered loss

            // Convert profit value to assets for reporting
            profit = profitValue.mulDiv(WadRayMath.RAY, currentRate);

            _mint(S, S.dragonRouter, profitShares);

            // update the dragon value debt
            YS.dragonRouterDebtInAssetValue += profitValue;

            emit DonationMinted(S.dragonRouter, profitShares, currentRate.rayToWad());
        } else if (currentValue < YS.totalDebtOwedToUserInAssetValue + YS.dragonRouterDebtInAssetValue) {
            // Loss - burn dragon shares first
            uint256 lossValue = YS.totalDebtOwedToUserInAssetValue + YS.dragonRouterDebtInAssetValue - currentValue;

            // Handle loss protection through dragon burning
            loss = _handleDragonLossProtection(S, YS, lossValue, currentRate);
        }

        // Update last report timestamp
        S.lastReport = uint96(block.timestamp);
        YS.lastReportedRate = currentRate;
        emit Harvest(msg.sender, currentRate.rayToWad());
        // `loss` here is a gross shortfall (level), not a delta; see report() NatSpec.
        emit Reported(profit, loss);

        return (profit, loss);
    }

    /**
     * @notice Get the last reported exchange rate (RAY precision)
     * @return Last reported exchange rate in RAY precision
     */
    function getLastRateRay() external view returns (uint256) {
        return _strategyYieldSkimmingStorage().lastReportedRate;
    }

    /**
     * @notice Check if the vault is currently insolvent
     * @return isInsolvent True if vault cannot cover user debt (excludes dragon shares as they absorb losses)
     */
    function isVaultInsolvent() external view returns (bool) {
        return _isVaultInsolvent();
    }

    /**
     * @notice Sets whether dragon-share burning is enabled for loss protection.
     * @dev Disabling burning is blocked while there is an unreported shortfall against
     *      combined user + dragon value debt. The shortfall must be reported while
     *      burning is still enabled so dragon shares absorb their pending first loss.
     * @param _enableBurning Whether to enable the burning mechanism
     */
    function setEnableBurning(bool _enableBurning) external override onlyManagement {
        StrategyData storage S = _strategyStorage();

        if (S.enableBurning && !_enableBurning) {
            require(!_hasPendingDragonBurn(S, _strategyYieldSkimmingStorage()), "report before disabling burning");
        }

        S.enableBurning = _enableBurning;
        emit UpdateBurningMechanism(_enableBurning);
    }

    /**
     * @notice Reports current accounting, then disables dragon burn loss protection.
     * @dev This explicit helper gives operators an atomic path for disabling burning
     *      without leaving a between-transaction window for rate changes.
     * @return profit Profit reported by the accounting sync
     * @return loss Loss reported by the accounting sync
     */
    function reportAndDisableBurning() external onlyManagement returns (uint256 profit, uint256 loss) {
        (profit, loss) = report();

        _strategyStorage().enableBurning = false;
        emit UpdateBurningMechanism(false);
    }

    /**
     * @dev Converts assets to shares using value debt approach with solvency awareness
     * @param S Strategy storage
     * @param assets Amount of assets to convert
     * @param rounding Rounding mode for division
     * @return Amount of shares equivalent in value (1 share = 1 unit of underlying-asset value, except in case of uncovered loss)
     */
    function _convertToShares(
        StrategyData storage S,
        uint256 assets,
        Math.Rounding rounding
    ) internal view virtual override returns (uint256) {
        if (_isVaultInsolvent()) {
            // Vault insolvent - use parent TokenizedStrategy logic
            return super._convertToShares(S, assets, rounding);
        } else {
            // Vault solvent - normal rate-based conversion
            uint256 currentRate = _currentRateRay();
            if (currentRate > 0) {
                return assets.mulDiv(currentRate, WadRayMath.RAY, rounding);
            } else {
                // Rate is 0 - asset has no value, use parent logic as fallback
                return super._convertToShares(S, assets, rounding);
            }
        }
    }

    /**
     * @dev Converts shares to assets using value debt approach with solvency awareness
     * @param S Strategy storage
     * @param shares Amount of shares to convert
     * @param rounding Rounding mode for division
     * @return Amount of assets user would receive in asset base units
     */
    function _convertToAssets(
        StrategyData storage S,
        uint256 shares,
        Math.Rounding rounding
    ) internal view virtual override returns (uint256) {
        if (_isVaultInsolvent()) {
            // Vault insolvent - use parent TokenizedStrategy logic
            return super._convertToAssets(S, shares, rounding);
        } else {
            // Vault solvent - normal rate-based conversion
            uint256 currentRate = _currentRateRay();
            if (currentRate > 0) {
                return shares.mulDiv(WadRayMath.RAY, currentRate, rounding);
            } else {
                // Rate is 0 - asset has no value, use parent logic as fallback
                return super._convertToAssets(S, shares, rounding);
            }
        }
    }

    /**
     * @dev Checks if the vault is currently insolvent
     * @return isInsolvent True if vault cannot cover user value debt
     */
    function _isVaultInsolvent() internal view returns (bool isInsolvent) {
        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();
        uint256 currentRate = _currentRateRay();
        uint256 currentVaultValue = S.totalAssets.mulDiv(currentRate, WadRayMath.RAY);

        // Vault is only insolvent if it cannot cover user debt
        // Dragon debt is excluded as dragon shares are designed to absorb losses
        return YS.totalDebtOwedToUserInAssetValue > 0 && currentVaultValue < YS.totalDebtOwedToUserInAssetValue;
    }

    /**
     * @dev Returns true when dragon shares still have a pending first-loss burn.
     *      This intentionally checks combined debt, not `_isVaultInsolvent()`, because
     *      users can still be fully covered while the dragon tranche is impaired.
     */
    function _hasPendingDragonBurn(
        StrategyData storage S,
        YieldSkimmingStorage storage YS
    ) internal view returns (bool) {
        if (_balanceOf(S, S.dragonRouter) == 0) return false;

        uint256 currentRate = _currentRateRay();
        uint256 currentVaultValue = S.asset.balanceOf(address(this)).mulDiv(currentRate, WadRayMath.RAY);
        uint256 totalDebt = YS.totalDebtOwedToUserInAssetValue + YS.dragonRouterDebtInAssetValue;

        return currentVaultValue < totalDebt;
    }

    /**
     * @dev Calculates the maximum amount of shares the dragon can redeem without making the vault unable to cover user debt
     * @return maxDragonRedeemable Maximum shares the dragon can redeem
     */
    function _maxDragonRedeemableShares() internal view returns (uint256 maxDragonRedeemable) {
        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();
        uint256 currentRate = _currentRateRay();
        uint256 currentVaultValue = S.totalAssets.mulDiv(currentRate, WadRayMath.RAY);

        // if enableBurning is false, dragon can redeem its full balance
        if (!S.enableBurning) {
            return _balanceOf(S, S.dragonRouter);
        }

        // If vault value is already below user debt, dragon cannot withdraw
        if (currentVaultValue <= YS.totalDebtOwedToUserInAssetValue) {
            return 0;
        }

        // Calculate excess value available for dragon (vault value - user debt)
        uint256 excessValue = currentVaultValue - YS.totalDebtOwedToUserInAssetValue;

        // Dragon can only redeem up to their debt or the excess value, whichever is lower
        uint256 dragonWithdrawableValue = Math.min(YS.dragonRouterDebtInAssetValue, excessValue);

        // Since dragon shares are 1:1 with value debt, return the value directly
        return dragonWithdrawableValue;
    }

    /**
     * @dev Blocks dragon router from withdrawing during vault insolvency
     * @param account The address to check (only blocks if it's the dragon router)
     */
    function _requireDragonSolvency(address account) internal view {
        StrategyData storage S = _strategyStorage();

        // if enableBurning is false, dragon can withdraw its full balance
        if (!S.enableBurning) {
            return;
        }

        // Only check if account is dragon router
        if (account == S.dragonRouter && _isVaultInsolvent()) {
            revert("Dragon cannot operate during insolvency");
        }
    }

    /**
     * @dev Checks vault solvency when dragon sends shares out (transfer, redeem, withdraw)
     * @param from Address shares are coming from
     * @param amount Amount of shares being moved
     * @dev Only checks when dragon is SENDING shares. Transfers TO dragon always improve
     *      user debt coverage so no check is needed for those.
     */
    function _requireDragonSolvencyAfterOperation(address from, uint256 amount) internal view {
        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();

        // if enableBurning is false, dragon can transfer freely
        if (!S.enableBurning) {
            return;
        }

        // Only check if dragon router is sending shares (user transfers to dragon always improve solvency)
        if (from != S.dragonRouter) {
            return;
        }

        // Calculate current vault value
        uint256 currentRate = _currentRateRay();
        uint256 currentVaultValue = S.totalAssets.mulDiv(currentRate, WadRayMath.RAY);

        // Dragon is sending shares - user debt will increase by the amount transferred
        uint256 currentUserDebt = YS.totalDebtOwedToUserInAssetValue;
        uint256 userDebtAfterTransfer = currentUserDebt + amount;
        if (currentVaultValue < userDebtAfterTransfer) {
            revert("Transfer would cause vault insolvency");
        }
    }

    /**
     * @dev Rebalances debt tracking when dragon transfers shares in or out
     */
    function _rebalanceDebtOnDragonTransfer(address from, address to, uint256 transferAmount) internal {
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();
        StrategyData storage S = _strategyStorage();

        // Direct transfer: shares represent underlying-asset value 1:1 in this system
        if (from == S.dragonRouter) {
            // Dragon sends shares: dragon loses debt obligation, users gain debt obligation
            require(YS.dragonRouterDebtInAssetValue >= transferAmount, "Insufficient dragon debt");
            unchecked {
                YS.dragonRouterDebtInAssetValue -= transferAmount;
            }
            YS.totalDebtOwedToUserInAssetValue += transferAmount;
        } else if (to == S.dragonRouter) {
            // User sends shares to dragon: users lose debt obligation, dragon gains debt obligation
            require(YS.totalDebtOwedToUserInAssetValue >= transferAmount, "Insufficient user debt");
            unchecked {
                YS.totalDebtOwedToUserInAssetValue -= transferAmount;
            }
            YS.dragonRouterDebtInAssetValue += transferAmount;
        }
    }

    /**
     * @dev Blocks all operations when vault is insolvent
     */
    function _requireVaultSolvency() internal view {
        if (_isVaultInsolvent()) {
            revert("Cannot operate when vault is insolvent");
        }
    }

    /**
     * @dev Get the current exchange rate scaled to RAY precision
     * @return Current exchange rate in RAY format (1e27 = 1.0)
     */
    function _currentRateRay() internal view virtual returns (uint256) {
        uint256 exchangeRate = IYieldSkimmingStrategy(address(this)).getCurrentExchangeRate();
        uint256 exchangeRateDecimals = IYieldSkimmingStrategy(address(this)).decimalsOfExchangeRate();

        // Convert directly to RAY (27 decimals) to avoid precision loss
        if (exchangeRateDecimals == 27) {
            return exchangeRate;
        } else if (exchangeRateDecimals < 27) {
            return exchangeRate * 10 ** (27 - exchangeRateDecimals);
        } else {
            return exchangeRate / 10 ** (exchangeRateDecimals - 27);
        }
    }

    /**
     * @dev Simulates how many dragon shares the lazy burn would remove from totalSupply.
     *      Used by maxWithdraw/maxRedeem view functions to reflect post-burn pricing.
     * @return burnAmount Number of dragon shares that would be burned (0 if no burn would occur)
     */
    function _simulateDragonBurnAmount() internal view returns (uint256 burnAmount) {
        StrategyData storage S = _strategyStorage();
        if (!S.enableBurning || !_isVaultInsolvent()) return 0;

        uint256 dragonBalance = _balanceOf(S, S.dragonRouter);
        if (dragonBalance == 0) return 0;

        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();
        uint256 currentRate = _currentRateRay();
        uint256 currentVaultValue = S.totalAssets.mulDiv(currentRate, WadRayMath.RAY);
        uint256 totalDebt = YS.totalDebtOwedToUserInAssetValue + YS.dragonRouterDebtInAssetValue;

        if (currentVaultValue >= totalDebt) return 0;

        return Math.min(totalDebt - currentVaultValue, dragonBalance);
    }

    /**
     * @dev Lazily burns dragon shares when the vault is insolvent, so that user exits
     *      are not diluted by stale junior capital in the totalSupply denominator.
     *      Only mutates state when burning is enabled AND the vault is currently insolvent.
     * @param S Strategy storage pointer
     * @param YS Yield skimming storage pointer
     */
    function _applyDragonLossProtectionIfNeeded(StrategyData storage S, YieldSkimmingStorage storage YS) internal {
        if (!S.enableBurning) return;
        // Only burn when the vault is insolvent (can't cover user debt).
        // This is the condition that triggers the pro-rata fallback in _convertToAssets,
        // which is where dragon shares in totalSupply cause dilution.
        if (!_isVaultInsolvent()) return;

        uint256 currentRate = _currentRateRay();
        uint256 currentVaultValue = S.totalAssets.mulDiv(currentRate, WadRayMath.RAY);
        uint256 totalDebt = YS.totalDebtOwedToUserInAssetValue + YS.dragonRouterDebtInAssetValue;

        if (currentVaultValue < totalDebt) {
            _handleDragonLossProtection(S, YS, totalDebt - currentVaultValue, currentRate);
        }
    }

    /**
     * @dev Internal function to handle loss protection by burning dragon shares
     * @param S Strategy storage pointer
     * @param YS Yield skimming storage pointer
     * @param lossValue Loss amount in underlying-asset value terms
     * @param currentRate Current exchange rate in RAY format
     * @return loss Loss amount in asset terms for reporting
     */
    function _handleDragonLossProtection(
        StrategyData storage S,
        YieldSkimmingStorage storage YS,
        uint256 lossValue,
        uint256 currentRate
    ) internal returns (uint256 loss) {
        uint256 dragonBalance = _balanceOf(S, S.dragonRouter);

        // Report the total loss in assets (gross loss before dragon protection)
        // Handle division by zero case when currentRate is 0
        if (currentRate > 0) {
            loss = lossValue.mulDiv(WadRayMath.RAY, currentRate);
        } else {
            // If rate is 0, total loss is all assets
            loss = S.totalAssets;
        }

        if (dragonBalance > 0 && S.enableBurning) {
            uint256 dragonBurn = Math.min(lossValue, dragonBalance);
            _burn(S, S.dragonRouter, dragonBurn);

            // Saturating subtraction: dragon-balance and dragon-debt should stay in sync,
            // but if accounting drifts (e.g. balance > debt) the raw `-=` would underflow
            // and brick loss protection. Match the defensive pattern used in redeem/withdraw.
            YS.dragonRouterDebtInAssetValue = YS.dragonRouterDebtInAssetValue > dragonBurn
                ? YS.dragonRouterDebtInAssetValue - dragonBurn
                : 0;

            emit DonationBurned(S.dragonRouter, dragonBurn, currentRate.rayToWad());
        }
    }

    /**
     * @notice Finalizes the dragon router change with proper debt accounting migration
     * @dev Migrates debt tracking when dragon router changes to maintain correct accounting.
     *      The solvency check runs AFTER debt migration so that:
     *      - Migrations that would restore solvency (new dragon holds user shares whose
     *        conversion to dragon debt drops user debt below vault value) are allowed.
     *      - Migrations that would create insolvency (old dragon balance becoming user
     *        debt pushes user debt above vault value) are blocked.
     *      A pre-migration check inspecting the old state misclassifies both directions.
     */
    function finalizeDragonRouterChange() external override {
        StrategyData storage S = _strategyStorage();
        YieldSkimmingStorage storage YS = _strategyYieldSkimmingStorage();

        require(S.pendingDragonRouter != address(0), "no pending change");
        require(block.timestamp >= S.dragonRouterChangeTimestamp + DRAGON_ROUTER_COOLDOWN, "cooldown not elapsed");

        address oldDragonRouter = S.dragonRouter;
        address newDragonRouter = S.pendingDragonRouter;

        // Burn any stale junior loss buffer before snapshotting balances so a
        // dust transfer to the old dragon cannot decide migration accounting.
        if (S.enableBurning) {
            _applyDragonLossProtectionIfNeeded(S, YS);
        }

        // Get balances before changing the router
        uint256 oldDragonBalance = _balanceOf(S, oldDragonRouter);
        uint256 newDragonBalance = _balanceOf(S, newDragonRouter);

        // Migrate debt accounting:
        // 1. Old dragon router's balance becomes user debt
        if (oldDragonBalance > 0) {
            YS.totalDebtOwedToUserInAssetValue += oldDragonBalance;
            if (YS.dragonRouterDebtInAssetValue >= oldDragonBalance) {
                YS.dragonRouterDebtInAssetValue -= oldDragonBalance;
            } else {
                YS.dragonRouterDebtInAssetValue = 0;
            }
        }

        // 2. New dragon router's balance (if any) becomes dragon debt
        if (newDragonBalance > 0) {
            YS.dragonRouterDebtInAssetValue += newDragonBalance;
            if (YS.totalDebtOwedToUserInAssetValue >= newDragonBalance) {
                YS.totalDebtOwedToUserInAssetValue -= newDragonBalance;
            } else {
                YS.totalDebtOwedToUserInAssetValue = 0;
            }
        }

        // Post-migration solvency check: only enforced when burning is enabled
        // (mirrors the gating used by _requireDragonSolvency / _maxDragonRedeemableShares).
        if (S.enableBurning) {
            require(!_isVaultInsolvent(), "Router change would cause insolvency");
        }

        // Now call the parent implementation to actually change the router
        S.dragonRouter = newDragonRouter;
        S.pendingDragonRouter = address(0);
        S.dragonRouterChangeTimestamp = 0;
        emit UpdateDragonRouter(newDragonRouter);
    }

    function _strategyYieldSkimmingStorage() internal pure returns (YieldSkimmingStorage storage S) {
        // Since STORAGE_SLOT is a constant, we have to put a variable
        // on the stack to access it from an inline assembly block.
        bytes32 slot = YIELD_SKIMMING_STORAGE_SLOT;
        assembly {
            S.slot := slot
        }
    }
}

