    function _buildDomainSeparator(StrategyData storage S) private view returns (bytes32) {
        return
            keccak256(
                abi.encode(EIP712DOMAIN_TYPEHASH, keccak256(bytes(S.name)), VERSION_HASH, block.chainid, address(this))
