    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        StrategyData storage S = _strategyStorage();
        if (block.chainid == S.cachedChainId) {
            return S.cachedDomainSeparator;
        }
        return _buildDomainSeparator(S);
    }
}

